import { useEffect, useState } from "react";
import { Alert, Box, Button } from "@mui/material";
import { useApp, useChat } from "../context";

export const ConnectionStatusEnum = {
  Connected: "connected",
  Error: "error",
  Pending: "pending",
} as const;

declare global {
  type ConnectionStatus = ObjectValues<typeof ConnectionStatusEnum>;
}

export const ConnectionStatusIndicator: React.FC = () => {
  const [{ connectionStatus }] = useApp();
  const [, { reconnect }] = useChat();
  const [showError, setShowError] = useState(false);

  useEffect(() => {
    let timeoutId: number;

    if (connectionStatus === ConnectionStatusEnum.Error) {
      // Delay showing the error banner by 1 second to prevent flashing
      timeoutId = window.setTimeout(() => {
        setShowError(true);
      }, 1000);
    } else {
      // Clear any pending timeout and hide the error immediately when connected
      setShowError(false);
    }

    return () => {
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
    };
  }, [connectionStatus]);

  if (!showError) return null;

  return (
    <Box
      sx={(theme) => ({
        padding: theme.spacing(2),
        width: "100%",
      })}
    >
      <Alert
        action={
          <Button color="error" onClick={reconnect} size="small">
            Reconnect
          </Button>
        }
        severity="error"
      >
        Connection lost
      </Alert>
    </Box>
  );
};
