import React from "react";
import { useApp } from "../../context";
import { Box, Fab } from "@mui/material";
import CloseIcon from "@kmx/mui-icons/KmxCloseFilled";

export const SurveyModal: React.FC = () => {
  const [{ config, isSurveyModalOpen }, { toggleSurveyModal }] = useApp();

  const onDismiss = () => toggleSurveyModal(false);

  return isSurveyModalOpen ? (
    <Box
      aria-labelledby="survey-modal"
      role="dialog"
      sx={() => ({
        bottom: 0,
        height: "100%",
        left: 0,
        overflow: "hidden",
        position: "absolute",
        width: "100%",
      })}
    >
      <Box
        sx={() => ({
          height: "100%",
          width: "100%",
        })}
      >
        <Fab
          color="default"
          aria-label="close survey"
          name="close survey"
          onClick={onDismiss}
          size="small"
          sx={{
            color: "white",
            position: "absolute",
            right: "8px",
            top: "8px",
          }}
        >
          <CloseIcon color="action" />
        </Fab>
        <Box
          component="iframe"
          id="suvey-modal"
          src={config.VITE_SURVEY_URL}
          sx={{
            border: "none",
            height: "100%",
            width: "100%",
          }}
          title="CarMax chat survey"
        />
      </Box>
    </Box>
  ) : null;
};
