import { PropsWithChildren } from "react";
import { CircularProgress, Stack, Typography } from "@mui/material";

interface Props {
  icon?: React.ReactNode;
  message: React.ReactNode;
  role?: "alert" | "status";
}

export const SystemEvent: React.FC<PropsWithChildren<Props>> = ({
  icon = <CircularProgress color="inherit" size="18px" />,
  message,
  role = "status",
}) => (
  <Stack
    aria-live="assertive"
    direction="row"
    role={role}
    sx={(theme) => ({
      alignItems: "center",
      gap: theme.spacing(1),
    })}
  >
    {icon}
    <Typography component="span" variant="body2">
      {message}
    </Typography>
  </Stack>
);
