import React, { useEffect, useRef } from "react";
import { Box, Fab, Stack } from "@mui/material";
import KeyboardArrowLeft from "@mui/icons-material/KeyboardArrowLeft";
import KeyboardArrowRight from "@mui/icons-material/KeyboardArrowRight";

export const Carousel: React.FC<React.PropsWithChildren> = ({ children }) => {
  const [activeIndex, setActiveIndex] = React.useState(0);
  const itemRefs = useRef<HTMLDivElement[]>([]);
  const carouselRef = useRef<HTMLDivElement>(null);
  const itemsCount = React.Children.count(children);

  const handleChangeIndex = (increment: 1 | -1) => {
    setActiveIndex((_activeIndex) => {
      const nextIndex = _activeIndex + increment;
      scrollToIndex(nextIndex);
      return nextIndex;
    });
  };

  const scrollToIndex = (index: number) => {
    if (itemRefs.current[index]) {
      itemRefs.current[index].scrollIntoView({
        behavior: "smooth",
        block: "nearest",
        inline: "center",
      });
    }
  };

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        const visibleItems = entries
          .filter((entry) => entry.isIntersecting)
          .sort((a, b) => b.intersectionRatio - a.intersectionRatio);

        if (visibleItems.length > 0) {
          const visibleIndex = itemRefs.current.findIndex(
            (ref) => ref === visibleItems[0].target,
          );
          setActiveIndex(visibleIndex);
        }
      },
      {
        root: carouselRef.current,
        threshold: 0.8, // How much of the element should be visible?
      },
    );

    itemRefs.current.forEach((el) => {
      if (el) observer.observe(el);
    });

    return () => {
      observer.disconnect();
    };
  }, []);

  return (
    <Box sx={{ position: "relative", width: "100%" }}>
      <Stack
        ref={carouselRef}
        sx={{
          flexDirection: "row",
          gap: 2,
          marginX: -4,
          overflowX: "scroll",
          paddingY: 2,
          paddingX: 4,
          scrollbarWidth: "none",
          scrollBehavior: "smooth",
          scrollSnapType: "x mandatory",
        }}
      >
        {React.Children.map(children, (child, index) => (
          <Box
            key={index}
            ref={(el: HTMLDivElement) => (itemRefs.current[index] = el)}
            sx={(theme) => ({
              flexShrink: 0,
              maxWidth: "90%",
              scrollMarginTop: theme.spacing(3),
              scrollSnapAlign: "center",
              width: "100%",
            })}
          >
            {child}
          </Box>
        ))}
      </Stack>
      <Fab
        aria-label="Back"
        color="default"
        disabled={activeIndex === 0}
        onClick={() => handleChangeIndex(-1)}
        size="small"
        sx={(theme) => ({
          backgroundColor: theme.palette.background.default,
          opacity: activeIndex === 0 ? 0 : 1,
          position: "absolute",
          left: 0,
          top: "50%",
          transition: theme.transitions.duration.shortest + "ms",
          ":hover": {
            backgroundColor: theme.palette.grey["200"],
          },
        })}
        title="Back"
      >
        <KeyboardArrowLeft />
      </Fab>
      <Fab
        aria-label="Next"
        color="default"
        disabled={activeIndex === itemsCount - 1}
        onClick={() => handleChangeIndex(1)}
        size="small"
        sx={(theme) => ({
          backgroundColor: theme.palette.background.default,
          opacity: activeIndex === itemsCount - 1 ? 0 : 1,
          position: "absolute",
          right: 0,
          top: "50%",
          transition: theme.transitions.duration.shortest + "ms",
          ":hover": {
            backgroundColor: theme.palette.grey["200"],
          },
        })}
        title="Next"
      >
        <KeyboardArrowRight />
      </Fab>
    </Box>
  );
};
