import { createRef, useRef, useEffect, useMemo } from "react";
import {
  IconButton,
  Stack,
  TextareaAutosize,
  useMediaQuery,
  useTheme,
} from "@mui/material";
import SendIcon from "@kmx/mui-icons/KmxPaperAirplaneFilled";
import { useApp, useChat } from "../../context";
import { ActivityTypesEnum } from "../../types";
import {
  ADOBE_DATA_LAYER,
  SessionStorageKeysEnum,
  trackAdobeDataLayer,
  useSessionStorage,
} from "../../util";
import { ConnectionStatusEnum } from "../ConnectionStatusIndicator";

export const TextInput: React.FC = () => {
  const [appState] = useApp();
  const [chat, { sendMessage }] = useChat();
  const { trackAdobeDataLayerEvent, getPageID } = trackAdobeDataLayer();
  const [draftMessage, setDraftMessage, removeDraftMessage] = useSessionStorage(
    SessionStorageKeysEnum.DraftMessage,
    "",
  );
  const formRef = createRef<HTMLFormElement>();
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const theme = useTheme();
  const isDesktop = useMediaQuery(theme.breakpoints.up("sm"));
  const inputIsEmpty = useMemo(
    () => draftMessage.trim().length === 0,
    [draftMessage],
  );
  const isDisabled =
    appState.connectionStatus === ConnectionStatusEnum.Error ||
    (chat.conversation?.skyeEnabled === false && !chat.isEscalated) ||
    chat.waitTimeSeconds > 0 ||
    chat.isSearching;

  const onSubmit = async (event?: React.FormEvent<HTMLFormElement>) => {
    if (event) event.preventDefault();
    const formData = new FormData(formRef.current!);
    const userMessage = formData.get("user-message");

    if (!userMessage || inputIsEmpty) return;

    sendMessage(userMessage as string);
    removeDraftMessage();
    formRef.current?.reset();

    if (
      chat.conversation?.transcript &&
      chat.conversation?.transcript.filter(
        (message) =>
          message.type == ActivityTypesEnum.Message &&
          message.senderId === appState.visitorId,
      ).length < 1
    ) {
      trackAdobeDataLayerEvent(ADOBE_DATA_LAYER.EVENT_NAMES.CHAT_SUBMITTED, {
        linkName: ADOBE_DATA_LAYER.LINK_NAMES.USER_CHAT_SUBMITTED,
        linkPosition: getPageID(),
      });
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      onSubmit();
    }
  };

  useEffect(() => {
    if (textareaRef.current && isDesktop) {
      textareaRef.current.focus();
    }
  }, [isDesktop]);

  return isDisabled ? null : (
    <Stack
      component="form"
      direction="row"
      noValidate
      onSubmit={onSubmit}
      ref={formRef}
      sx={(theme) => ({
        alignItems: "flex-end",
        borderTop: "1px solid " + theme.palette.divider,
        transition: theme.transitions.duration.standard + "ms",
      })}
    >
      <TextareaAutosize
        autoComplete="off"
        defaultValue={draftMessage}
        disabled={isDisabled}
        id="Skye-Text-Input"
        name="user-message"
        onChange={(event) => setDraftMessage(event.target.value.trim())}
        onKeyDown={handleKeyDown}
        placeholder="Ask a question..."
        ref={textareaRef}
        maxLength={1500}
        maxRows={9}
        style={{
          appearance: "none",
          backgroundColor: "transparent",
          border: "none",
          flexGrow: 1,
          fontFamily: "inherit",
          fontSize: "1rem",
          outline: "none",
          padding: "1rem",
          resize: "none",
        }}
      />
      <IconButton
        aria-label="send"
        color="primary"
        disabled={inputIsEmpty}
        id="Skye-Send-Message-Button"
        name="send"
        size="large"
        type="submit"
      >
        <SendIcon height="6" width="6" />
      </IconButton>
    </Stack>
  );
};
