// we must set up addition properties for window in order to send events to the EDDL
declare global {
  interface Window {
    digitalData: {
      product: AdobeDataLayer.Product[];
      user: AdobeDataLayer.User[];
      finance?: AdobeDataLayer.FinanceAttributes;
      lead?: AdobeDataLayer.LeadAttributes;
      recommendations?: AdobeDataLayer.Recommendations;
      page: AdobeDataLayer.Page;
    };
    adobeDataLayer: {
      event: string;
      pageInfo?: AdobeDataLayer.PageInfoAttributes;
      linkDetails?: {
        name: string;
        position: string;
      };
    }[];
  }
}
interface customDetailsTypes {
  [key: string]: string | customDetailsTypes;
}

interface adobeDataLayerDetails {
  linkName: string;
  linkPosition: string;
  customDetails?: customDetailsTypes;
}

