export const trackAdobeDataLayer = () => {
  const trackAdobeDataLayerEvent = (
    eventName: string,
    details?: adobeDataLayerDetails,
  ) => {
    if (details) {
      window?.adobeDataLayer?.push({
        event: eventName,
        linkDetails: {
          name: details.linkName,
          position: details.linkPosition,
        },
        ...details.customDetails,
      });
    } else {
      window?.adobeDataLayer?.push({
        event: eventName,
      });
    }
  };

  const getPageID = () => {
    return window.adobeDataLayer?.[0]?.pageInfo
      ? window.adobeDataLayer[0].pageInfo.pageID
      : window.digitalData
        ? window.digitalData.page.pageInfo.pageID
        : "";
  };

  return { trackAdobeDataLayerEvent, getPageID };
};

/**
 * Waits for the Adobe Data Layer to become available on the window object.
 * Returns a cleanup function that should be called to cancel the polling.
 *
 * @param callback Function to call when Adobe Data Layer is available or timeout occurs
 * @param options Configuration options for polling behavior
 * @returns Cleanup function to cancel polling
 */
export const waitForAdobeDataLayer = (
  callback: () => void,
  options: AdobeDataLayer.WaitForAdobeDataLayerOptions = {},
): (() => void) => {
  const { pollInterval = 50, maxWaitTime = 5000, logWarning = true } = options;

  // If already available, call immediately
  if (window.adobeDataLayer) {
    callback();
    return () => {}; // No-op cleanup
  }

  const startTime = Date.now();
  let timeoutId: number;

  const poll = () => {
    if (window.adobeDataLayer) {
      callback();
      return;
    }

    const elapsed = Date.now() - startTime;
    if (elapsed < maxWaitTime) {
      timeoutId = window.setTimeout(poll, pollInterval);
    } else {
      // Timeout reached - call callback anyway
      if (logWarning) {
        console.warn(
          `Adobe Data Layer failed to initialize within ${maxWaitTime}ms, proceeding anyway`,
        );
      }
      callback();
    }
  };

  // Start polling
  timeoutId = window.setTimeout(poll, pollInterval);

  // Return cleanup function
  return () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
    }
  };
};
