import React, { useState } from "react";
import {
  Divider,
  IconButton,
  Menu,
  MenuItem,
  Stack,
  Typography,
} from "@mui/material";
import MoreHorizIcon from "@kmx/mui-icons/KmxMoreHorizontalFilled";
import CloseIcon from "@kmx/mui-icons/KmxCloseFilled";
import SkyeLogoIcon from "../../assets/skye_logo_icon.svg";
import { useApp, useChat } from "../../context";
import {
  ADOBE_DATA_LAYER,
  buildUsername,
  trackAdobeDataLayer,
} from "../../util";

export const Header: React.FC = () => {
  const [, appActions] = useApp();
  const [chat, chatActions] = useChat();
  const [menuAnchor, setMenuAnchor] = useState<null | HTMLElement>(null);
  const menuOpen = Boolean(menuAnchor);
  const { trackAdobeDataLayerEvent } = trackAdobeDataLayer();

  let headerName = "Skye";
  let liveAgentInitials = "";

  const liveAgent = (chat.conversation?.members || [])
    .filter((m) => m.associateIdentity.associateId)
    .find((m) => !m.leftAt);

  if (liveAgent) {
    headerName = buildUsername(
      liveAgent.associateIdentity.firstName,
      liveAgent.associateIdentity.lastName,
    );
    liveAgentInitials = (
      liveAgent.associateIdentity.firstName[0] +
      (liveAgent.associateIdentity.lastName ?? "")[0]
    ).toUpperCase();
  }

  const onEnd = () => {
    setMenuAnchor(null);
    trackAdobeDataLayerEvent(ADOBE_DATA_LAYER.EVENT_NAMES.CTA_CLICK, {
      linkName: ADOBE_DATA_LAYER.LINK_NAMES.END,
      linkPosition: ADOBE_DATA_LAYER.LINK_POSITIONS.CHAT,
    });
    appActions.toggleChatWindow(0);
    chatActions.resetChat();
    appActions.toggleSurveyModal(false);
  };

  const onMinimize = () => {
    setMenuAnchor(null);
    trackAdobeDataLayerEvent(ADOBE_DATA_LAYER.EVENT_NAMES.CTA_CLICK, {
      linkName: ADOBE_DATA_LAYER.LINK_NAMES.MINIMIZE,
      linkPosition: ADOBE_DATA_LAYER.LINK_POSITIONS.CHAT,
    });
    appActions.toggleChatWindow();
    appActions.toggleSurveyModal(false);
  };

  const onRestart = () => {
    setMenuAnchor(null);
    trackAdobeDataLayerEvent(ADOBE_DATA_LAYER.EVENT_NAMES.CTA_CLICK, {
      linkName: ADOBE_DATA_LAYER.LINK_NAMES.RESTART,
      linkPosition: ADOBE_DATA_LAYER.LINK_POSITIONS.CHAT,
    });
    chatActions.resetChat();
    appActions.toggleSurveyModal(false);
  };

  const onFAQ = () => {
    setMenuAnchor(null);
    trackAdobeDataLayerEvent(ADOBE_DATA_LAYER.EVENT_NAMES.CTA_CLICK, {
      linkName: ADOBE_DATA_LAYER.LINK_NAMES.FAQ,
      linkPosition: ADOBE_DATA_LAYER.LINK_POSITIONS.CHAT,
    });
    window.open("/help-center", "_blank");
  };

  const onShareFeedback = () => {
    setMenuAnchor(null);
    trackAdobeDataLayerEvent(ADOBE_DATA_LAYER.EVENT_NAMES.CTA_CLICK, {
      linkName: ADOBE_DATA_LAYER.LINK_NAMES.SHARE_FEEDBACK,
      linkPosition: ADOBE_DATA_LAYER.LINK_POSITIONS.CHAT,
    });
    appActions.toggleSurveyModal();
  };

  return (
    <Stack
      direction="row"
      gap={1}
      sx={{
        alignItems: "center",
        justifyContent: "space-between",
        padding: 1,
      }}
    >
      <Stack
        aria-label={liveAgent ? "Live Agent" : "Skye"}
        role="heading"
        direction="row"
        sx={{
          flexGrow: 1,
          gap: 1,
          paddingLeft: 1,
        }}
      >
        {liveAgent ? (
          <Stack
            sx={(theme) => ({
              alignItems: "center",
              justifyContent: "center",
              width: theme.spacing(4),
              height: theme.spacing(4),
              backgroundColor: theme.palette.grey[200],
              borderRadius: "50%",
            })}
          >
            <Typography>{liveAgentInitials}</Typography>
          </Stack>
        ) : (
          // @ts-expect-error unrecognized SVGR attributes
          <SkyeLogoIcon
            fill="var(--hzn-text-color-neutral)"
            width="32"
            style={{ marginTop: "-4px" }}
          />
        )}
        <Typography
          component="p"
          sx={{
            fontWeight: "bold",
            fontSize: "1.25rem",
          }}
        >
          {headerName}
        </Typography>
      </Stack>
      <IconButton
        aria-controls={menuOpen ? "skye-menu" : undefined}
        aria-expanded={menuOpen ? "true" : undefined}
        aria-haspopup="true"
        aria-label="options"
        id="Skye-Menu-Button"
        name="options"
        onClick={(event) => setMenuAnchor(event.currentTarget)}
      >
        <MoreHorizIcon fontSize="inherit" />
      </IconButton>
      <Menu
        anchorEl={menuAnchor}
        anchorOrigin={{
          vertical: "bottom",
          horizontal: "right",
        }}
        disablePortal
        disableScrollLock
        id="Skye-Menu"
        open={menuOpen}
        onClose={() => setMenuAnchor(null)}
        transformOrigin={{
          vertical: "top",
          horizontal: "right",
        }}
      >
        <MenuItem
          aria-label="feedback"
          id="Skye-Menu-Feedback"
          onClick={onShareFeedback}
        >
          Share feedback
        </MenuItem>
        <Divider />
        <MenuItem aria-label="faq" id="Skye-Menu-FAQ" onClick={onFAQ}>
          FAQ &amp; support
        </MenuItem>
        <Divider />
        <MenuItem
          aria-label="restart"
          id="Skye-Menu-Restart-Chat"
          onClick={onRestart}
        >
          Restart chat
        </MenuItem>
        <MenuItem aria-label="end" id="Skye-Menu-End-Chat" onClick={onEnd}>
          End chat
        </MenuItem>
      </Menu>
      <IconButton
        aria-label="minimize"
        id="Skye-Minimize-Chat-Button"
        name="minimize"
        onClick={onMinimize}
      >
        <CloseIcon fontSize="inherit" />
      </IconButton>
    </Stack>
  );
};
