import React, { useEffect, useRef, useState } from "react";
import { motion, AnimatePresence, Transition } from "framer-motion";
import { Fab, Stack } from "@mui/material";
import CloseIcon from "@kmx/mui-icons/KmxCloseFilled";
import { useOnClickOutside } from "usehooks-ts";
import { LocalStorageKeysEnum, useLocalStorage } from "../../util";
import { useApp, useAppInsights, useChat } from "../../context";
import { ActivityTypesEnum } from "../../types";
import { Microsurvey } from "./Microsurvey";
import Rating from "./Rating";

const ANIMATION_CONFIG = {
  initial: {
    opacity: 0,
    scale: 0.95,
    y: 10,
  },
  animate: {
    opacity: 1,
    scale: 1,
    transition: {
      delay: 1.0,
    } as Transition,
    y: 0,
  },
  exit: (delay?: boolean) => ({
    opacity: 0,
    scale: 0.95,
    transition: {
      delay: delay ? 2.0 : 0.0,
    } as Transition,
    y: 10,
  }),
} as const;

const DISPLAY_TIMEOUT = 10000; // 10 second
const MICROSURVEY_LABEL = "Microsurvey";
const CHAT_RATING_LABEL = "Chat Rating";

export const FeedbackModal: React.FC = () => {
  const { trackEvent } = useAppInsights();
  const [{ toggleState, visitorId }] = useApp();
  const [{ conversation }] = useChat();
  const [conversationData, setLocalConversation] = useLocalStorage(
    LocalStorageKeysEnum.ConversationData,
  );
  const [hover, setHover] = useState(false);
  const [timedOut, setTimedOut] = useState(false);
  const [delayedShow, setDelayedShow] = useState(false);
  const timeoutId = useRef<number>();
  const microsurveyFocused = useRef<boolean>(false);
  const ref = useRef<HTMLDivElement>() as React.RefObject<HTMLDivElement>;

  const hasRating = conversationData?.rating !== undefined;
  const hasSurveyFeedback = conversationData?.surveyFeedback !== undefined;
  const userMessages =
    conversation?.transcript.filter(
      (m) =>
        m.senderId === visitorId && m.category === ActivityTypesEnum.Message,
    ) || [];

  // Show the rating prompt if the following criteria are met:
  const show =
    // The chat window has just been closed
    toggleState > 1 &&
    toggleState % 2 === 0 &&
    // The user has not yet given feedback on microsurvey
    !hasSurveyFeedback &&
    // The user has sent at least one message for the current conversation
    userMessages?.length > 0 &&
    // The user has never dismissed the rating prompt for the current conversation
    !conversationData.dismissed &&
    // The chat rating component has not yet timed out for the current conversation
    !timedOut;

  const onDismiss = (dismissSource: string) => {
    setLocalConversation({
      ...conversationData,
      dismissed: true,
    });
    trackEvent(`${dismissSource} Dismissed`, {
      conversationId: conversation?.id,
      dismissed: true,
    });
  };

  const handleMicrosurveyFocus = () => {
    microsurveyFocused.current = true;
    setHover(true);
  };

  const handleMicrosurveyBlur = () => {
    microsurveyFocused.current = false;
    setHover(false);
  };

  const onClickedOutside = () => {
    setTimedOut(true);
    clearTimeout(timeoutId.current);
  };

  useOnClickOutside(ref, onClickedOutside);

  useEffect(() => {
    if (!conversation) return;

    if (show) {
      trackEvent("Chat Rating Shown", { conversationId: conversation?.id });
      setDelayedShow(true);
    } else {
      /*
        hack to ensure <AnimatePresence> renders its children
        for one more frame prior to removal
        in order for CSS animations to work
      */
      requestAnimationFrame(() => setDelayedShow(false));
      if (hasRating && !hasSurveyFeedback) onDismiss(MICROSURVEY_LABEL);
    }
  }, [conversation, show]);

  useEffect(() => {
    console.log(hover);
    if (!show || hover || microsurveyFocused.current) return;

    timeoutId.current = window.setTimeout(
      () => setTimedOut(true),
      DISPLAY_TIMEOUT,
    );

    return () => {
      clearTimeout(timeoutId.current);
      timeoutId.current = undefined;
    };
  }, [hover, show]);

  return (
    <AnimatePresence>
      {delayedShow ? (
        <Stack
          animate={ANIMATION_CONFIG.animate}
          component={motion.div}
          exit={ANIMATION_CONFIG.exit(hasSurveyFeedback)}
          id="Skye-Rating"
          initial={ANIMATION_CONFIG.initial}
          onHoverEnd={() => setHover(false)}
          onHoverStart={() => setHover(true)}
          ref={ref}
          sx={{
            alignItems: "flex-end",
            gap: 2,
            position: "relative",
          }}
        >
          <Fab
            aria-label="close chat rating"
            color="default"
            name="close chat rating"
            onClick={() => onDismiss(CHAT_RATING_LABEL)}
            size="small"
          >
            <CloseIcon />
          </Fab>
          <Stack
            component={motion.div}
            sx={(theme) => ({
              backgroundColor: theme.palette.background.paper,
              borderRadius: 1,
              padding: 2,
              boxShadow: theme.shadows[8],
            })}
          >
            {hasRating ? (
              <Microsurvey
                selectedRating={conversationData.rating}
                onFocus={handleMicrosurveyFocus}
                onBlur={handleMicrosurveyBlur}
              />
            ) : (
              <Rating />
            )}
          </Stack>
        </Stack>
      ) : null}
    </AnimatePresence>
  );
};

export default FeedbackModal;
