import { ADOBE_DATA_LAYER, trackAdobeDataLayer } from "../util";
import { useApp } from "../context";
import React from "react";

export const FAB_V1: React.FC = () => {
  const [appState, actions] = useApp();
  const { trackAdobeDataLayerEvent, getPageID } = trackAdobeDataLayer();

  const onClickHandler = () => {
    trackAdobeDataLayerEvent(ADOBE_DATA_LAYER.EVENT_NAMES.FAB_CLICKED, {
      linkName: ADOBE_DATA_LAYER.LINK_NAMES.FAB,
      linkPosition: getPageID(),
    });
    actions.toggleChatWindow();
  };

  return appState.isChatOpen ? null : (
    <button
      aria-label="Open Skye chat"
      data-testid="chatfab"
      // Never change this ID! other teams, such as our analytics & data team, depend on this!
      id="startChatFab"
      name="CarMax Chat"
      onClick={onClickHandler}
      style={{
        alignItems: "center",
        backgroundColor: "#005ab8",
        border: "none",
        borderRadius: "100%",
        boxShadow:
          "0px 5px 5px -3px rgba(0,38,77,.14),0px 8px 10px rgba(0,38,77,.1),0px 3px 14px 2px rgba(0,38,77,.08)",
        color: "#fff",
        cursor: "pointer",
        display: "flex",
        height: "60px",
        justifyContent: "center",
        transform: "translateY(0px)",
        width: "60px",
      }}
    >
      <svg
        aria-hidden="true"
        aria-labelledby="chatTitleId"
        fill="none"
        height="32"
        role="img"
        style={{
          transform: "rotateY(180deg)",
        }}
        viewBox="0 0 32 32"
        width="32"
        xmlns="http://www.w3.org/2000/svg"
      >
        <title id="chatTitleId">Chat Bubble Icon</title>
        <path
          fillRule="evenodd"
          clipRule="evenodd"
          d="M4 6.66667C4 5.19391 5.19391 4 6.66667 4H25.3333C26.8061 4 28 5.1939 28 6.66667V20C28 21.4728 26.8061 22.6667 25.3333 22.6667H16.4677L12.3325 25.9748C10.5865 27.3716 8 26.1285 8 23.8925V22.6667H6.66667C5.19391 22.6667 4 21.4728 4 20V6.66667ZM25.3333 6.66667L6.66667 6.66667V20H8C9.47276 20 10.6667 21.1939 10.6667 22.6667V23.8925L14.8019 20.5844C15.2747 20.2061 15.8622 20 16.4677 20H25.3333L25.3333 6.66667Z"
          fill="#fff"
        ></path>
      </svg>
    </button>
  );
};
