import { Divider, List, ListItem, Stack, Typography } from "@mui/material";
import MUICard from "@mui/material/Card";
import CardContent from "@mui/material/CardContent";
import CardMedia from "@mui/material/CardMedia";
import KmxMPG from "@kmx/mui-icons/KmxFuelGaugeStroked";
import KmxLocation from "@kmx/mui-icons/KmxCompassStroked";
import KmxFeatures from "@kmx/mui-icons/KmxChecklistStroked";
import { formatMileage } from "../../util";

interface Props {
  activityId: string;
  vehicle: Entities.Vehicle.Model;
}

export const VehicleCard: React.FC<Props> = ({ vehicle }) => {
  let title = vehicle.year + " " + vehicle.make + " " + vehicle.model;

  if (vehicle.trim) title += " " + vehicle.trim;

  return (
    <MUICard
      component="a"
      href={vehicle.url}
      sx={(theme) => ({
        display: "block",
        textDecoration: "none",
        ":hover": {
          backgroundColor: theme.palette.grey[100],
        },
        transition: theme.transitions.duration.shortest + "ms",
      })}
      target="_blank"
      variant="outlined"
    >
      <CardMedia
        image={`https://img2.carmax.com/assets/${vehicle.stockNumber}/hero.jpg?width=600`}
        sx={{ height: 200 }}
        title={title}
      />
      <CardContent
        sx={{
          display: "flex",
          flexDirection: "column",
          gap: 2,
          paddingBottom: 2,
          "&:last-child": {
            paddingBottom: 2,
          },
        }}
      >
        <Typography
          component="h3"
          variant="h6"
          sx={{
            overflow: "hidden",
            textOverflow: "ellipsis",
            textWrap: "nowrap",
          }}
        >
          {title}
        </Typography>
        <Stack direction="row" gap={1}>
          {vehicle.displayPrice ? (
            <Typography component="h3" variant="h6">
              {vehicle.displayPrice}
            </Typography>
          ) : undefined}
          {vehicle.displayMileage && vehicle.displayPrice ? (
            <Divider
              flexItem
              orientation="vertical"
              sx={{ alignSelf: "center", height: 16 }}
            />
          ) : null}
          {vehicle.displayMileage ? (
            <Typography component="h3" variant="h6">
              {vehicle.displayMileage}
            </Typography>
          ) : vehicle.mileage ? (
            <Typography component="h3" variant="h6">
              {formatMileage(vehicle.mileage)}
            </Typography>
          ) : null}
        </Stack>
        <List
          dense
          sx={(theme) => ({
            color: theme.palette.text.secondary,
            paddingTop: 0,
            paddingBottom: 0,
          })}
        >
          {vehicle.geoCity && vehicle.state ? (
            <ListItem disableGutters sx={{ gap: 1 }}>
              <KmxLocation />
              <Typography component="span" variant="body2">
                {vehicle.geoCity}, {vehicle.state}
              </Typography>
            </ListItem>
          ) : null}
          {vehicle.mpgCity && vehicle.mpgHighway ? (
            <ListItem disableGutters sx={{ gap: 1 }}>
              <KmxMPG />
              <Typography component="span" variant="body2">
                {vehicle.mpgCity} city / {vehicle.mpgHighway} highway
              </Typography>
            </ListItem>
          ) : null}
          {vehicle.features && vehicle.features.length > 0 ? (
            <ListItem disableGutters sx={{ gap: 1 }}>
              <KmxFeatures />
              <Typography
                component="span"
                sx={{
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  whiteSpace: "nowrap",
                }}
                variant="body2"
              >
                {vehicle.features.join(", ")}
              </Typography>
            </ListItem>
          ) : null}
        </List>
      </CardContent>
    </MUICard>
  );
};
