import React, { useMemo, type PropsWithChildren } from "react";
import {
  ApplicationInsights,
  ICustomProperties,
} from "@microsoft/applicationinsights-web";
import {
  AppInsightsContext,
  ReactPlugin,
  useAppInsightsContext,
} from "@microsoft/applicationinsights-react-js";
import { config } from "./configuration";
import { ErrorBoundary } from "./ErrorBoundary";

const isMock = config.VITE_APPINSIGHTS_KEY === "mock";

export const AppInsightsProvider: React.FC<PropsWithChildren> = ({
  children,
}) => {
  // Microsoft AppInsights events & error tracking
  // https://learn.microsoft.com/en-us/azure/azure-monitor/app/javascript-framework-extensions?tabs=react

  const reactAppInsights = useMemo(() => {
    if (isMock) return null;

    const _reactAppInsights = new ReactPlugin();
    const appInsights = new ApplicationInsights({
      config: {
        disableAjaxTracking: true,
        disableExceptionTracking: true,
        disableFetchTracking: true,
        extensions: [_reactAppInsights],
        instrumentationKey: config.VITE_APPINSIGHTS_KEY,
      },
    });

    appInsights.loadAppInsights();
    return _reactAppInsights;
  }, []);

  if (reactAppInsights) {
    return (
      <ErrorBoundary appInsights={reactAppInsights}>
        <AppInsightsContext.Provider value={reactAppInsights}>
          {children}
        </AppInsightsContext.Provider>
      </ErrorBoundary>
    );
  } else {
    return children;
  }
};

export const useAppInsights = () => {
  const appInsightsContext = useAppInsightsContext();

  if (appInsightsContext) {
    return {
      trackEvent: (eventName: string, eventData?: ICustomProperties) =>
        appInsightsContext.trackEvent({ name: eventName }, eventData),
    };
  } else {
    return {
      trackEvent: console.log,
    };
  }
};
