import { Alert, Button, Stack } from "@mui/material";
import { useChat } from "../../context";
import { EventTypesEnum } from "../../types";
import { skyeOfflineText } from "./Offline";

interface Props {
  hasChatHistory?: boolean;
}

export const OfflineAlert: React.FC<Props> = ({ hasChatHistory }) => {
  const [chat, actions] = useChat();
  const showOfflineAlert =
    chat.conversation?.skyeEnabled === false &&
    !chat.isEscalated &&
    Number.isNaN(chat.waitTimeSeconds);

  const onClick = () => {
    actions.sendEvent(EventTypesEnum.AgentHandoff, EventTypesEnum.AgentHandoff);
  };

  if (!showOfflineAlert) return null;

  return (
    <Stack sx={{ padding: 2 }}>
      {(() => {
        if (hasChatHistory && chat.agentAvailability) {
          return (
            <Alert
              action={
                <Button
                  onClick={onClick}
                  size="small"
                  variant="outlined"
                  color="inherit"
                >
                  Connect
                </Button>
              }
              severity="info"
              variant="filled"
              icon={false}
            >
              <strong>{skyeOfflineText}</strong>
              <br />
              Experts are available to help
            </Alert>
          );
        } else if (hasChatHistory && !chat.agentAvailability) {
          return (
            <Alert severity="info" variant="filled" icon={false}>
              <strong>{skyeOfflineText}</strong>
            </Alert>
          );
        } else if (!hasChatHistory && chat.agentAvailability) {
          return (
            <Alert
              action={
                <Button
                  onClick={onClick}
                  size="small"
                  variant="outlined"
                  color="inherit"
                >
                  Connect
                </Button>
              }
              severity="info"
              variant="filled"
              icon={false}
            >
              <strong>Connect to a live agent?</strong>
              <br />
              Experts are available to help
            </Alert>
          );
        } else if (!hasChatHistory && !chat.agentAvailability) {
          return null;
        }
      })()}
    </Stack>
  );
};
