import React, { PropsWithChildren } from "react";
import KmxCheckFilled from "@kmx/mui-icons/KmxCheckFilled";
import { Divider, Link, Stack, Typography } from "@mui/material";
import { useApp, useAppInsights, useChat } from "../../context";
import { Feedback } from "../Feedback/Feedback";
import { SystemEvent } from "..";

type Props = {
  content?: string;
  title?: string;
  url: string;
  activityId: string;
};

export const Snippet: React.FC<PropsWithChildren<Props>> = ({
  content,
  url,
  activityId,
  title,
}) => {
  const [{ visitorId }] = useApp();
  const [{ conversation }] = useChat();
  const { trackEvent } = useAppInsights();
  const isLink = Boolean(!content);

  const onClickHandler = () => {
    const eventName = isLink ? "LINK_CLICKED" : "SNIPPET_LINK_CLICKED";

    trackEvent(eventName, {
      answer: content,
      conversationId: conversation?.id,
      URL: url,
      visitorId,
    });
  };

  return (
    <Stack
      data-testid={isLink ? "link" : "snippet"}
      sx={{
        gap: 2,
      }}
    >
      {!isLink ? (
        <SystemEvent
          icon={<KmxCheckFilled color="disabled" />}
          message="Found an answer on carmax.com"
        />
      ) : null}
      <Link
        aria-label="Open on carmax.com in a new tab"
        href={url}
        onClick={onClickHandler}
        sx={{
          textDecoration: "none",
        }}
        title={title}
        target="_blank"
      >
        <Stack
          sx={(theme) => ({
            "&:hover": {
              backgroundColor: theme.palette.grey[200],
            },
            backgroundColor: theme.palette.grey[100],
            border: "1px solid " + theme.palette.divider,
            borderRadius: 1.5,
            color: theme.palette.text.primary,
            transition: theme.transitions.duration.standard + "ms",
          })}
        >
          {!isLink ? (
            <>
              <Typography
                variant="body2"
                sx={(theme) => ({
                  lineClamp: 7,
                  padding: theme.spacing(3) + " " + theme.spacing(2),
                })}
              >
                "{content}"
              </Typography>
              <Divider />
            </>
          ) : null}
          <Stack
            gap={0.5}
            sx={(theme) => ({
              padding: theme.spacing(2),
            })}
          >
            {title && (
              <Typography
                variant="h6"
                sx={{
                  lineClamp: 2,
                  overflow: "visible",
                }}
              >
                {title}
              </Typography>
            )}
            <Typography color="info" variant="body2">
              carmax.com
            </Typography>
          </Stack>
        </Stack>
      </Link>
      <Feedback
        activityId={activityId}
        eventName={
          isLink ? "LINK_FEEDBACK_CLICKED" : "SNIPPET_FEEDBACK_CLICKED"
        }
        metadata={{
          answer: content,
          URL: url,
        }}
      />
    </Stack>
  );
};
