import { useEffect } from "react";
import { useMediaQuery, useScrollLock } from "usehooks-ts";
import { CircularProgress, Stack, useTheme } from "@mui/material";
import {
  ChatTranscript,
  ConnectionStatusIndicator,
  EthnioScreener,
  Header,
  Offline,
  OfflineAlert,
  SurveyModal,
  TextInput,
  Welcome,
} from ".";
import { useApp, useAppInsights, useChat } from "../context";
import { ActivityTypesEnum, EventTypesEnum } from "../types";

export const ChatWindow = () => {
  const [appState] = useApp();
  const [chat] = useChat();
  const { trackEvent } = useAppInsights();
  const { lock, unlock } = useScrollLock();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const renderableActivities = chat.conversation?.transcript.filter(
    (activity) => {
      if (activity.category === ActivityTypesEnum.Message) return true;
      if (activity.type === EventTypesEnum.AgentHandoff) return true;
    },
  );
  const showTranscript =
    (renderableActivities && renderableActivities.length > 0) ||
    chat.isSearching ||
    chat.isThinking ||
    chat.isTyping;

  useEffect(() => {
    if (appState.isChatOpen && isMobile) {
      lock();
    } else if (appState.isChatOpen) {
      trackEvent("Chat with CarMax");
    } else {
      unlock();
    }
  }, [appState.isChatOpen, isMobile]);

  return appState.isChatOpen ? (
    <Stack
      sx={(theme) => ({
        backgroundColor: theme.palette.background.default,
        borderRadius: 0,
        bottom: "70px",
        boxShadow: 5,
        left: 0,
        overflow: "hidden",
        position: "fixed",
        right: 0,
        top: 0,
        width: "100%",
        [theme.breakpoints.up("sm")]: {
          borderRadius: 1.5,
          bottom: 0,
          height: "calc(100vh - 1rem)",
          maxHeight: "46rem",
          minHeight: "15rem",
          position: "relative",
          width: "25rem",
        },
      })}
    >
      <Header />
      {chat.isLoading ? (
        <Stack
          sx={{
            alignItems: "center",
            justifyContent: "center",
            height: "100%",
          }}
        >
          <CircularProgress aria-label="loading" />
        </Stack>
      ) : (
        <>
          {(() => {
            if (showTranscript) {
              return <ChatTranscript />;
            } else if (chat.conversation?.skyeEnabled === true) {
              return <Welcome />;
            } else {
              return <Offline />;
            }
          })()}
          <OfflineAlert
            hasChatHistory={
              renderableActivities && renderableActivities.length > 0
            }
          />
          <ConnectionStatusIndicator />
          <TextInput />
          <SurveyModal />
          <EthnioScreener />
        </>
      )}
    </Stack>
  ) : null;
};
