import { PropsWithChildren, useEffect, useRef, useState } from "react";
import { Badge, Box, Chip, Fab, Stack, SxProps, Theme } from "@mui/material";
import CheckIcon from "@kmx/mui-icons/KmxCheckFilled";
import WavingHandIcon from "@kmx/mui-icons/KmxHandWavingStroked";
import KeyboardArrowDownIcon from "@kmx/mui-icons/KmxArrowDownFilled";
import WarningIcon from "@kmx/mui-icons/KmxWarningStroked";
import SearchIcon from "@kmx/mui-icons/KmxSearchStroked";
import { useDebounceCallback } from "usehooks-ts";
import { useApp, useChat } from "../context";
import {
  ActivityTypesEnum,
  AgentTypesEnum,
  AttachmentTypesEnum,
  EventTypesEnum,
} from "../types";
import { buildUsername } from "../util";
import {
  AgentMessage,
  AgentSearch,
  BotMessage,
  Carousel,
  SuggestedActions,
  SystemEvent,
  Snippet,
  UserMessage,
  VehicleCard,
} from ".";
import { vehicleSearchRenderTypesEnum } from "../types/activities/attachments/VehicleSearch";

interface ChatEntryProps {
  userRole: "Bot" | "Live agent" | "System" | "User";
  sx?: Partial<SxProps<Theme>>;
}

const ChatEntry: React.FC<PropsWithChildren<ChatEntryProps>> = ({
  children,
  userRole,
  sx,
}) => (
  <Stack
    aria-label={`${userRole} message`}
    role="listitem"
    sx={(theme) => ({
      ...(sx as object),
      direction: "column",
      gap: 2,
      scrollMarginTop: theme.spacing(3),
    })}
  >
    {children}
  </Stack>
);

export const ChatTranscript: React.FC = () => {
  const [state] = useApp();
  const [chat] = useChat();
  const [isScrolledUp, setScrolledUp] = useState(false);
  const [unreadMessageElement, setUnreadMessageElement] =
    useState<HTMLDivElement>();
  const chatContainerRef = useRef<HTMLDivElement>(null);
  const rem = parseFloat(getComputedStyle(document.documentElement).fontSize);

  // derivatives
  const chatMessages =
    chat.conversation?.transcript.filter(
      (message) => message.category === ActivityTypesEnum.Message,
    ) || [];

  const shouldRenderMessage = (message: Conversations.Activities.Activity) => {
    if (
      message.category === ActivityTypesEnum.Message ||
      (message.category === ActivityTypesEnum.Event &&
        [
          EventTypesEnum.UserJoined,
          EventTypesEnum.UserLeft,
          EventTypesEnum.Snippet,
          EventTypesEnum.LiveAgentUnavailable,
          EventTypesEnum.Link,
          // @ts-expect-error incompatible array types
        ].includes(message.type))
    ) {
      return true;
    } else {
      return false;
    }
  };

  const onClickScrollButton = () => {
    if (unreadMessageElement) {
      scrollToFirstUnreadMessage();
    } else {
      scrollToBottom();
    }
  };

  const onScroll = useDebounceCallback(() => {
    const scrollBottom =
      (chatContainerRef.current?.clientHeight ?? 0) +
      (chatContainerRef.current?.scrollTop ?? 0);
    const margin = 2 * rem;

    if (scrollBottom < (chatContainerRef.current?.scrollHeight ?? 0) - margin) {
      setScrolledUp(true);
    } else {
      setScrolledUp(false);
      setUnreadMessageElement(undefined);
    }
  }, 100);

  const scrollToBottom = (behavior: ScrollBehavior = "smooth") => {
    if (!chatContainerRef.current) return;

    window.setTimeout(
      () =>
        chatContainerRef.current?.scrollTo({
          behavior,
          top: chatContainerRef.current.scrollHeight,
        }),
      1,
    );

    setUnreadMessageElement(undefined);
  };

  const scrollToFirstUnreadMessage = () => {
    if (!chatContainerRef.current || !unreadMessageElement) return;

    window.setTimeout(
      () =>
        unreadMessageElement.scrollIntoView({
          behavior: "smooth",
          block: "start",
        }),
      1,
    );

    setUnreadMessageElement(undefined);
  };

  const shouldRenderAttachments = (
    attachments: Conversations.Activities.Messages.Attachments.Base[],
    index: number,
    array: Conversations.Activities.Activity[],
  ) => {
    if (!attachments || attachments.length <= 0) return false;

    // We should only render 'suggested actions' if it's for the most recent message
    if (
      attachments.every(
        (attachment) =>
          attachment.contentType === AttachmentTypesEnum.SuggestedActions,
      ) &&
      index !== array.length - 1
    )
      return false;

    return true;
  };

  useEffect(() => {
    const lastMessageUser =
      chatMessages.slice().pop()?.senderId === state.visitorId;

    if (lastMessageUser) {
      scrollToBottom();
    } else if (
      !lastMessageUser &&
      !unreadMessageElement &&
      chatContainerRef.current
    ) {
      const latestMessageElement = Array.from(chatContainerRef.current.children)
        .filter((element) => element.ariaLabel?.includes("Bot"))
        .slice()
        .pop() as HTMLDivElement;
      setUnreadMessageElement(latestMessageElement);
    }
  }, [chat.conversation?.transcript.length]);

  useEffect(() => {
    if (!unreadMessageElement) return;

    if (!isScrolledUp) {
      scrollToFirstUnreadMessage();
    }
  }, [unreadMessageElement]);

  useEffect(() => {
    scrollToBottom("instant");
  }, []);

  return (
    <Stack
      aria-label="Chat Transcript"
      aria-live="polite"
      aria-relevant="additions text"
      id="Skye-Chat-Transcript"
      onScroll={onScroll}
      ref={chatContainerRef}
      role="log"
      sx={{
        flexGrow: 1,
        gap: 3,
        overflowX: "hidden",
        overflowY: "auto",
        padding: 2,
      }}
      tabIndex={-1}
    >
      {chat.conversation?.transcript.map((message, i, arr) => {
        const fromUser = message.senderId === state.visitorId;
        const agent = chat.conversation?.members.find(
          (member) => member.associateIdentity.associateId === message.senderId,
        );
        const isCarousel = message.attachments.some(
          (attachment) =>
            attachment.contentType === AttachmentTypesEnum.VehicleSearch,
        );

        if (!shouldRenderMessage(message)) return null;

        return (
          <ChatEntry
            key={message.id}
            userRole={fromUser ? "User" : agent ? "Live agent" : "Bot"}
            sx={{
              flexDirection: isCarousel ? "column-reverse" : undefined,
            }}
          >
            {(() => {
              switch (message.category) {
                case ActivityTypesEnum.Event: {
                  switch (message.type) {
                    case EventTypesEnum.UserJoined: {
                      const content: Conversations.Activities.Events.UserJoinedContent =
                        JSON.parse(message.content);

                      return (
                        <SystemEvent
                          aria-label="User joined event"
                          icon={<CheckIcon color="disabled" />}
                          message={
                            buildUsername(
                              content.associateIdentity.firstName,
                              content.associateIdentity.lastName,
                            ) + " has joined the chat"
                          }
                          role="alert"
                        />
                      );
                    }
                    case EventTypesEnum.UserLeft: {
                      const content: Conversations.Activities.Events.UserLeftContent =
                        JSON.parse(message.content);

                      return (
                        <SystemEvent
                          aria-label="User left event"
                          icon={<WavingHandIcon color="disabled" />}
                          message={
                            buildUsername(
                              content.associateIdentity?.firstName ??
                                "Participant",
                              content.associateIdentity?.lastName,
                            ) + " has left the chat"
                          }
                          role="alert"
                        />
                      );
                    }
                    case EventTypesEnum.LiveAgentUnavailable: {
                      return (
                        <SystemEvent
                          aria-label="Live agent unavailable event"
                          icon={<WarningIcon color="disabled" />}
                          message={"Something went wrong"}
                          role="alert"
                        />
                      );
                    }
                  }
                  break;
                }
                case ActivityTypesEnum.Message: {
                  const content: Conversations.Activities.Messages.Message["content"] =
                    message.content;

                  if (fromUser) {
                    return <UserMessage>{content}</UserMessage>;
                  } else if (agent) {
                    return (
                      <AgentMessage
                        activityId={message.id}
                        name={buildUsername(
                          agent.associateIdentity.firstName,
                          agent.associateIdentity.lastName,
                        )}
                      >
                        {content}
                      </AgentMessage>
                    );
                  } else {
                    const isLatestBotMessage =
                      chatMessages
                        ?.filter(
                          (message) =>
                            message.senderId === AgentTypesEnum.GenerativeAgent,
                        )
                        .slice()
                        .pop()?.id === message.id;
                    const isLatestFeedbackMessage =
                      chatMessages
                        ?.filter(
                          (message) =>
                            message.senderId ===
                              AgentTypesEnum.GenerativeAgent &&
                            message.feedback,
                        )
                        .slice()
                        .pop()?.id === message.id;

                    return (
                      <BotMessage
                        activityId={message.id}
                        agentType={chat.conversation!.agentType}
                        defaultFeedbackValue={message.feedback}
                        showAuthorName={
                          (chat.conversation?.members?.length ?? 0) > 1
                        }
                        showDisclaimer={isLatestBotMessage}
                        showFeedbackSurvey={isLatestFeedbackMessage}
                      >
                        {content}
                      </BotMessage>
                    );
                  }
                }
              }
            })()}
            {shouldRenderAttachments(message.attachments, i, arr)
              ? message.attachments.map((attachment, j) => {
                  switch (attachment.contentType) {
                    case AttachmentTypesEnum.VehicleSearch: {
                      const carouselData: Conversations.Activities.Messages.Attachments.VehicleSearchContent =
                        JSON.parse(attachment.contentValue);

                      switch (carouselData.renderType) {
                        case vehicleSearchRenderTypesEnum.Carousel: {
                          return (
                            <Stack key={i + "-" + j}>
                              {/* <Typography
                                                    aria-label='Carousel title'
                                                    component='h3'
                                                    sx={{ textTransform: 'capitalize' }}
                                                    variant='subtitle1'
                                                >Used {carouselData.query}for sale</Typography> */}
                              <Carousel>
                                {carouselData.items.map((vehicle, i) => (
                                  <VehicleCard
                                    activityId={message.id}
                                    vehicle={vehicle}
                                    key={i}
                                  />
                                ))}
                              </Carousel>
                              <Box>
                                <Chip
                                  clickable
                                  color="info"
                                  component="a"
                                  href={carouselData.searchUrl}
                                  icon={<SearchIcon />}
                                  label="See all results"
                                  target="_blank"
                                  variant="weak"
                                />
                              </Box>
                            </Stack>
                          );
                        }
                      }
                      break;
                    }
                    case AttachmentTypesEnum.Link: {
                      const {
                        Title,
                        Url,
                      }: Conversations.Activities.Messages.Attachments.LinkContent =
                        JSON.parse(attachment.contentValue);

                      return (
                        <Snippet
                          activityId={message.id}
                          key={i + "-" + j}
                          title={Title}
                          url={Url}
                        />
                      );
                    }
                    case AttachmentTypesEnum.Snippet: {
                      const {
                        TopAnswerText,
                        TopSearchResultTitle,
                        TopSearchResultURI,
                      }: Conversations.Activities.Messages.Attachments.SnippetContent =
                        JSON.parse(attachment.contentValue);

                      return (
                        <Snippet
                          activityId={message.id}
                          content={TopAnswerText}
                          key={i + "-" + j}
                          title={TopSearchResultTitle}
                          url={TopSearchResultURI}
                        />
                      );
                    }
                    case AttachmentTypesEnum.SuggestedActions: {
                      const contentValue: Conversations.Activities.Messages.Attachments.SuggestedActionsContent =
                        JSON.parse(attachment.contentValue);

                      return (
                        <SuggestedActions
                          key={i + "-" + j}
                          suggestedActions={contentValue.suggestedActions}
                        />
                      );
                    }
                  }
                })
              : null}
          </ChatEntry>
        );
      })}
      {chat.waitTimeSeconds > 0 ? (
        <ChatEntry userRole="System">
          <AgentSearch waitTimeSeconds={chat.waitTimeSeconds} />
        </ChatEntry>
      ) : null}
      {chat.isSearching ? (
        <ChatEntry userRole="System">
          <SystemEvent message="Searching for an answer" />
        </ChatEntry>
      ) : null}
      {chat.isTyping ? (
        <ChatEntry userRole="System">
          <SystemEvent message="Typing..." />
        </ChatEntry>
      ) : null}
      {chat.isThinking && !(chat.isSearching || chat.isTyping) ? (
        <ChatEntry userRole="System">
          <SystemEvent message="Thinking..." />
        </ChatEntry>
      ) : null}
      <Badge
        badgeContent={unreadMessageElement ? " " : undefined}
        color="error"
        overlap="circular"
        sx={(theme) => ({
          bottom: theme.spacing(5),
          left: "50%",
          marginTop: "-40px",
          opacity: isScrolledUp ? 1.0 : 0.0,
          pointerEvents: isScrolledUp ? "all" : "none",
          position: "absolute",
          textAlign: "center",
          transform: `translate(-50%, ${isScrolledUp ? "-50%" : "0"})`,
          transition: theme.transitions.duration.standard + "ms",
          visibility: isScrolledUp ? "visible" : "hidden",
          "& .MuiBadge-badge": {
            zIndex: theme.zIndex.fab + 1,
          },
        })}
      >
        <Fab
          aria-label="scroll to bottom"
          id="Skye-Scroll-Transcript-Button"
          onClick={onClickScrollButton}
          size="small"
        >
          <KeyboardArrowDownIcon />
        </Fab>
      </Badge>
    </Stack>
  );
};
