import { useEffect, useState } from "react";
import { SystemEvent } from "..";

interface Props {
  delayMs?: number;
  waitTimeSeconds: number;
}

export const AgentSearch: React.FC<Props> = ({
  delayMs = 1000,
  waitTimeSeconds,
}) => {
  const [showTime, setShowTime] = useState(false);

  useEffect(() => {
    const agentSearchTimeoutId = setTimeout(() => setShowTime(true), delayMs);
    return () => clearTimeout(agentSearchTimeoutId);
  }, [delayMs]);

  return (
    <SystemEvent
      message={(() => {
        if (!showTime) return <span>Finding a teammate</span>;
        const waitTimeMinutes = Math.floor(waitTimeSeconds / 60);
        return waitTimeMinutes <= 0 ? (
          <span>
            Estimated wait: <strong>less than a minute</strong>
          </span>
        ) : waitTimeMinutes === 1 ? (
          <span>
            Estimated wait: <strong>1 minute</strong>
          </span>
        ) : (
          <span>
            Estimated wait: <strong>{waitTimeMinutes} minutes</strong>
          </span>
        );
      })()}
      role="alert"
    />
  );
};
