import { AttachmentTypesEnum } from ".";

export const vehicleSearchRenderTypesEnum = {
  NotSet: "NottSet",
  List: "List",
  Table: "Table",
  Compact: "Compact",
  Carousel: "Carousel",
} as const;

declare global {
  namespace Conversations.Activities.Messages.Attachments {
    interface VehicleSearch extends Attachments.Base {
      contentType: typeof AttachmentTypesEnum.VehicleSearch;
      contentValue: string;
    }

    interface VehicleSearchContent {
      /** The top vehicle results for display in the UI */
      items: Array<Entities.Vehicle.Model>;
      /** The search query used to retrieve the results, represented as natural language */
      query: string;
      /** What component should represent the search results */
      renderType: (typeof vehicleSearchRenderTypesEnum)[keyof typeof vehicleSearchRenderTypesEnum];
      /** The search URL for the query, which represents the query as token instead of parameters */
      searchUrl: string;
      /** The total number of search results available */
      totalCount: number;
    }
  }
}

export {};
