import { useState } from "react";
import { IconButton, Link, Stack, Typography } from "@mui/material";
import ThumbsUpIcon from "@kmx/mui-icons/KmxThumbsUpStroked";
import ThumbsUpFilledIcon from "@kmx/mui-icons/KmxThumbsUpFilled";
import ThumbsDownIcon from "@kmx/mui-icons/KmxThumbsDownStroked";
import ThumbsDownFilledIcon from "@kmx/mui-icons/KmxThumbsDownFilled";
import { useApp, useAppInsights, useChat } from "../../context";
import { config } from "../../context/configuration";
import { EventTypesEnum } from "../../types";

export const FeedbackValuesEnum = {
  Positive: 1,
  Negative: -1,
} as const;

declare global {
  type FeedbackValues = ObjectValues<typeof FeedbackValuesEnum>;
}

interface FeedbackProps {
  activityId: string;
  defaultValue?: FeedbackValues;
  eventName: string;
  metadata?: Record<string, unknown>;
  showDisclaimer?: boolean;
  showSurvey?: boolean;
}

export const Feedback: React.FC<FeedbackProps> = ({
  activityId,
  defaultValue,
  eventName,
  metadata,
  showDisclaimer,
  showSurvey,
}) => {
  const { trackEvent } = useAppInsights();
  const [chat, chatActions] = useChat();
  const [appState, { toggleSurveyModal }] = useApp();
  const [selectedValue, setSelectedValue] = useState<
    FeedbackValues | undefined
  >(defaultValue);

  if (!chat.conversation) return;

  // Survey URL
  const surveyUrl = new URL(config.VITE_SURVEY_URL);
  surveyUrl.searchParams.set("VisitorID", appState.visitorId);
  surveyUrl.searchParams.set("ConversationID", chat.conversation.id);
  surveyUrl.searchParams.set(
    "OriginURL",
    window.location.href ?? "https://www.carmax.com",
  );
  surveyUrl.searchParams.set("CiamID", appState.myKmxId ?? "");

  const onSelection = async (
    event: React.MouseEvent<HTMLButtonElement, MouseEvent>,
  ) => {
    event.preventDefault();
    const feedback = parseInt(event.currentTarget.value) as FeedbackValues;

    trackEvent(eventName, {
      value: feedback,
      activityData: {
        activityId: activityId,
        conversationId: chat.conversation?.id,
        visitorId: appState.visitorId,
        ...metadata,
      },
    });
    setSelectedValue(feedback);
    chatActions.sendEvent(EventTypesEnum.MessageFeedback, {
      activityId,
      feedback,
    });
  };

  const onSurveyOpen = (e: React.MouseEvent<HTMLAnchorElement, MouseEvent>) => {
    e.preventDefault();
    toggleSurveyModal(true);
  };

  return (
    <Stack
      sx={{
        alignItems: "center",
        flexDirection: "row",
        gap: 1,
      }}
    >
      <Stack
        sx={{
          flexDirection: "row",
        }}
      >
        <IconButton
          data-testid={FeedbackValuesEnum.Negative}
          disabled={Boolean(selectedValue) || undefined}
          name="feedback"
          onClick={onSelection}
          size="small"
          type="button"
          value={FeedbackValuesEnum.Negative}
        >
          {selectedValue === FeedbackValuesEnum.Negative ? (
            <ThumbsDownFilledIcon fontSize="small" />
          ) : (
            <ThumbsDownIcon fontSize="small" />
          )}
        </IconButton>
        <IconButton
          data-testid={FeedbackValuesEnum.Positive}
          disabled={Boolean(selectedValue) || undefined}
          name="feedback"
          onClick={onSelection}
          size="small"
          type="button"
          value={FeedbackValuesEnum.Positive}
        >
          {selectedValue === FeedbackValuesEnum.Positive ? (
            <ThumbsUpFilledIcon fontSize="small" />
          ) : (
            <ThumbsUpIcon fontSize="small" />
          )}
        </IconButton>
      </Stack>
      {selectedValue && showSurvey ? (
        <Typography variant="caption">
          Thanks for letting us know!{" "}
          <Link href="#" onClick={onSurveyOpen}>
            Take feedback survey
          </Link>
        </Typography>
      ) : showDisclaimer ? (
        <Typography color="textDisabled" variant="caption">
          Skye can make mistakes. Please check for accuracy.
        </Typography>
      ) : null}
    </Stack>
  );
};
