import React, { PropsWithChildren } from "react";
import Markdown, { Components } from "react-markdown";
import remarkGfm from "remark-gfm";
import {
  Box,
  Divider,
  Link,
  Stack,
  Theme,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
} from "@mui/material";
import { Feedback } from "..";

interface Props {
  className?: string;
}

const nestedListStyles = (theme: Theme) => ({
  ul: {
    paddingLeft: theme.spacing(2),
  },
  ol: {
    paddingLeft: theme.spacing(2),
  },
  li: {
    paddingTop: theme.spacing(0.5),
    paddingBottom: theme.spacing(0.5),
  },
  "li:has(>img)": {
    listStyleType: "none",
    marginLeft: theme.spacing(1.5),
  },
});

const markdownHorizonComponents: Components = {
  a: (props) => (
    <Link target="_blank" href={props.href}>
      {props.children}
    </Link>
  ),
  blockquote: (props) => (
    <Typography
      component="blockquote"
      sx={(theme) => ({
        borderLeft: "1px solid " + theme.palette.divider,
        padding: "0.5rem 1rem",
      })}
    >
      {props.children}
    </Typography>
  ),
  h1: ({ children }) => (
    <Typography component="h1" variant="h5">
      {children}
    </Typography>
  ),
  h2: ({ children }) => (
    <Typography component="h2" variant="h6">
      {children}
    </Typography>
  ),
  h3: ({ children }) => (
    <Typography component="h3" variant="h6">
      {children}
    </Typography>
  ),
  h4: ({ children }) => (
    <Typography component="h4" variant="h6">
      {children}
    </Typography>
  ),
  hr: () => <Divider />,
  p: ({ children }) => <Typography>{children}</Typography>,
  ol: ({ children }) => (
    <Typography component="ol" sx={nestedListStyles}>
      {children}
    </Typography>
  ),
  ul: ({ children }) => (
    <Typography component="ul" sx={nestedListStyles}>
      {children}
    </Typography>
  ),
  img: ({ src, alt }) => (
    <Box
      alt={alt}
      component="img"
      src={src}
      sx={{
        aspectRatio: "4/3",
        borderRadius: "0.5rem",
        margin: "0.5rem 0",
        objectFit: "cover",
        width: "100%",
      }}
    />
  ),
  table: ({ children }) => (
    <TableContainer
      component={Paper}
      sx={{
        margin: "1rem 0",
        maxWidth: "100%",
        overflowX: "auto",
        "& .MuiTable-root": {
          fontSize: "0.875rem",
          minWidth: "max-content",
        },
        // Restrict image sizes within table cells
        "& img": {
          maxWidth: "150px !important",
          maxHeight: "150px !important",
          width: "auto !important",
          height: "auto !important",
          objectFit: "contain !important",
          aspectRatio: "unset !important",
          borderRadius: "0.25rem",
          margin: "0.25rem 0",
        },
      }}
    >
      <Table size="small" sx={{ tableLayout: "auto" }}>
        {children}
      </Table>
    </TableContainer>
  ),
  thead: ({ children }) => <TableHead>{children}</TableHead>,
  tbody: ({ children }) => <TableBody>{children}</TableBody>,
  tr: ({ children }) => <TableRow>{children}</TableRow>,
  th: ({ children }) => (
    <TableCell
      component="th"
      sx={{
        fontWeight: "bold",
        backgroundColor: (theme) => theme.palette.grey[50],
        whiteSpace: "nowrap",
        padding: "8px 16px",
      }}
    >
      {children}
    </TableCell>
  ),
  td: ({ children }) => (
    <TableCell
      sx={{
        whiteSpace: "nowrap",
        padding: "8px 16px",
      }}
    >
      {children}
    </TableCell>
  ),
};

interface AgentProps extends Props {
  activityId: string;
  name: string;
}

export const AgentMessage: React.FC<PropsWithChildren<AgentProps>> = ({
  children,
  name,
}) => {
  return (
    <Stack>
      <Typography aria-label="Live agent name" variant="caption">
        {name}
      </Typography>
      <Stack
        sx={(theme) => ({
          backgroundColor: theme.palette.grey[100],
          borderRadius: 1,
          borderBottomLeftRadius: 2,
          gap: 1,
          maxWidth: "80%",
          padding: "1rem 1.5rem",
          wordBreak: "break-word",
        })}
      >
        <Typography>{children}</Typography>
      </Stack>
    </Stack>
  );
};

interface BotProps extends Props {
  activityId: string;
  agentType: Conversations.Conversation["agentType"];
  defaultFeedbackValue?: -1 | 1;
  showDisclaimer?: boolean;
  showAuthorName: boolean;
  showFeedack?: boolean;
  showFeedbackSurvey?: boolean;
}

export const BotMessage: React.FC<PropsWithChildren<BotProps>> = ({
  activityId,
  children,
  defaultFeedbackValue,
  showAuthorName,
  showDisclaimer,
  showFeedack = true,
  showFeedbackSurvey,
}) => {
  return (
    <Stack
      sx={{
        gap: 1,
      }}
    >
      {showAuthorName ? (
        <Typography aria-label="Skye" variant="caption">
          Skye
        </Typography>
      ) : null}
      <Stack
        sx={(theme) => ({
          backgroundColor: theme.palette.background.paper,
          borderRadius: 1,
          borderBottomLeftRadius: 2,
          gap: 1,
          padding: "1rem 0rem",
          wordBreak: "break-word",
        })}
      >
        <Markdown
          components={markdownHorizonComponents}
          remarkPlugins={[remarkGfm]}
        >
          {children as string}
        </Markdown>
      </Stack>
      {showFeedack ? (
        <Feedback
          activityId={activityId}
          defaultValue={defaultFeedbackValue}
          eventName="GENERATIVE_AGENT_FEEDBACK_CLICKED"
          showDisclaimer={showDisclaimer}
          showSurvey={showFeedbackSurvey}
        />
      ) : null}
    </Stack>
  );
};

export const UserMessage: React.FC<PropsWithChildren<Props>> = ({
  children,
}) => {
  return (
    <Stack
      alignSelf="flex-end"
      sx={(theme) => ({
        justifySelf: "flex-end",
        backgroundColor: theme.palette.grey[100],
        borderRadius: 1,
        borderBottomRightRadius: 2,
        color: theme.palette.text.primary,
        gap: 1,
        maxWidth: "80%",
        padding: "1rem 1.5rem",
        wordBreak: "break-word",
      })}
    >
      <Typography>{children}</Typography>
    </Stack>
  );
};
