export type ConversationRating =
  Window["localStorage"]["skye-conversation-ids"]["rating"];

export const RATING_EMOJIS = ["😠", "🙁", "😐", "🙂", "😄"] as const;

export const getEmojiFromRating = (
  rating: ConversationRating | undefined,
): string => {
  if (rating === undefined) return "😐";
  const index = rating + 2;
  return RATING_EMOJIS[index] || "😐";
};
