import React from "react";
import { Button, Stack } from "@mui/material";
import { useChat } from "../context";

interface Props {
  suggestedActions: Array<Conversations.Activities.Messages.Attachments.SuggestedAction>;
}

export const SuggestedActions: React.FC<Props> = ({ suggestedActions }) => {
  const [, { sendMessage }] = useChat();

  const onClick = (event: React.MouseEvent<HTMLButtonElement>) => {
    const message = event.currentTarget.innerHTML;
    sendMessage(message);
  };

  return (
    <Stack
      data-testid="suggested-actions"
      direction="row"
      sx={{
        gap: 1,
        flexWrap: "wrap",
        justifyContent: "flex-end",
      }}
    >
      {suggestedActions.map((suggestedAction) => (
        <Button
          color="inherit"
          key={suggestedAction.id}
          name={suggestedAction.id}
          onClick={onClick}
          value={suggestedAction.value}
        >
          {suggestedAction.label}
        </Button>
      ))}
    </Stack>
  );
};
