import React from "react";
import * as ReactDOM from "react-dom/client";
import { themeConfig } from "@kmx/mui-resources";
import { ThemeProvider, createTheme } from "@mui/material/styles";
import { deepmerge } from "@mui/utils";
import ScopedCssBaseline from "@mui/material/ScopedCssBaseline";
import createCache from "@emotion/cache";
import { Stack } from "@mui/material";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { ReactQueryDevtools } from "@tanstack/react-query-devtools";
import { CacheProvider } from "@emotion/react";
import { AppInsightsProvider, AppProvider, ChatProvider } from "./context";
import { ChatWindow, FAB_V1, FeedbackModal } from "./components";
import { isExcludedPage } from "./util";
import "./main.css";

if (isExcludedPage()) {
  console.log("Skye excluded page. Exiting.");
} else {
  let chatWindow = document.getElementById("SkyeChat");

  if (!chatWindow) {
    const section = document.createElement("section", { is: "SkyeChat" });
    section.id = "SkyeChat";
    section.classList.add("chat-window");
    document.body.appendChild(section);
    chatWindow = document.getElementById("SkyeChat");
  }

  if (!chatWindow)
    throw new Error(
      'Could not initialize Skye Chat: no element with id "SkyeChat" exists.',
    );

  ReactDOM.createRoot(chatWindow).render(
    <React.StrictMode>
      <AppInsightsProvider>
        <CacheProvider
          value={createCache({
            key: "skye-styles",
            container: chatWindow,
            // prepend: true,
            // stylisPlugins: [wrapInLayer('chakra')],
          })}
        >
          <ThemeProvider
            theme={createTheme(
              deepmerge(themeConfig, {
                colorSchemes: { dark: false },
              }),
            )}
          >
            <ScopedCssBaseline>
              <QueryClientProvider
                client={
                  new QueryClient({
                    defaultOptions: {
                      queries: {
                        retry: false,
                      },
                    },
                  })
                }
              >
                <AppProvider>
                  <ChatProvider>
                    <Stack
                      sx={(theme) => ({
                        [theme.breakpoints.down("md")]: {
                          bottom: "70px",
                        },
                        alignItems: "flex-end",
                        bottom: 0,
                        gap: 2,
                        justifyContent: "flex-end",
                        padding: 2,
                        position: "fixed",
                        right: 0,
                      })}
                    >
                      <FeedbackModal />
                      <ChatWindow />
                      <FAB_V1 />
                    </Stack>
                  </ChatProvider>
                </AppProvider>
                <ReactQueryDevtools buttonPosition="bottom-left" />
              </QueryClientProvider>
            </ScopedCssBaseline>
          </ThemeProvider>
        </CacheProvider>
      </AppInsightsProvider>
    </React.StrictMode>,
  );
}
