import {
  type PropsWithChildren,
  createContext,
  useContext,
  useEffect,
  useState,
} from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import publicIp from "public-ip";
import { useApp, useAppInsights } from ".";
import {
  FetcherError,
  fetcher,
  LocalStorageKeysEnum,
  useFeatures,
  useLocalStorage,
  useCookies,
  CookieKeysEnum,
  ViewedVehicle,
  ADOBE_DATA_LAYER,
  trackAdobeDataLayer,
} from "../util";
import {
  ActivityTypesEnum,
  AgentTypesEnum,
  EventTypesEnum,
  MemberRolesEnum,
} from "../types";
import { ConnectionStatusEnum } from "../components";

type ChatContextType = [
  {
    agentAvailability: boolean;
    conversation?: Conversations.Conversation;
    error: Error | null;
    isCancellable: boolean;
    isEscalated: boolean;
    isLoading: boolean;
    isSearching: boolean;
    isThinking: boolean;
    isTyping: boolean;
    latestActivityIsSnippet: boolean;
    reconnections: number;
    waitTimeSeconds: number;
    websocket?: WebSocket;
  },
  {
    reconnect: () => void;
    resetChat: () => void;
    sendEvent: <T extends Conversations.Activities.Events.Types>(
      eventType: T,
      eventContent: Conversations.Activities.Events.Content<T>,
    ) => void;
    sendMessage: (text: string) => void;
  },
];

export const ChatContext = createContext<ChatContextType>([
  {},
  {},
] as ChatContextType);

interface Props {
  value?: Partial<ChatContextType>;
}

export const ChatProvider: React.FC<PropsWithChildren<Props>> = ({
  children,
  value,
}) => {
  const [{ isChatOpen, visitorId, config }, { setConnectionStatus }] = useApp();
  const [websocket, setWebsocket] = useState<WebSocket>();
  const [isTyping, setTyping] = useState(false);
  const [waitTimeSeconds, setWaitTime] = useState(NaN);
  const [isSearching, setSearching] = useState(false);
  const [isThinking, setThinking] = useState(false);
  const [isCancellable, setCancellable] = useState(false);
  const [reconnections, setReconnect] = useState(0);
  const [latestActivityIsSnippet, setLatestActivityIsSnippet] = useState(false);
  const [isRefreshed, setIsRefreshed] = useState(false);
  const queryClient = useQueryClient();
  const [conversationData, setLocalConversation, removeLocalConversation] =
    useLocalStorage(LocalStorageKeysEnum.ConversationData);
  const [
    conversationState,
    setLocalConversationState,
    removeLocalConversationState,
  ] = useLocalStorage(LocalStorageKeysEnum.ConversationState);
  const [features] = useFeatures();
  const [myKmxCookie] = useCookies(CookieKeysEnum.MyKmxId);
  const [visitorCookie] = useCookies(CookieKeysEnum.VisitorId);
  const [visitCounterCookie] = useCookies(CookieKeysEnum.VisitCounter);
  const [viewedVehiclesCookie] = useCookies(CookieKeysEnum.ViewedVehicles);
  const [adCookie] = useCookies(CookieKeysEnum.AdCode);
  const [storeIdCookie] = useCookies(CookieKeysEnum.StoreId);
  const [nearestStore] = useLocalStorage(LocalStorageKeysEnum.NearestStore, {
    // @ts-expect-error we only need store.Id
    store: { Id: "7201" },
  });
  const { trackEvent } = useAppInsights();
  const { trackAdobeDataLayerEvent } = trackAdobeDataLayer();
  const isNewConversation = !conversationData.id;

  const { data: newConversation, isLoading: createConversationLoading } =
    useQuery({
      enabled: isChatOpen && isNewConversation,
      queryKey: ["conversation"],
      queryFn: async () => {
        try {
          return await fetcher.post<
            Conversations.API.Post.Response,
            Conversations.API.Post.Body
          >(`${config.VITE_CONVERSATION_SERVICE_URL}/conversations`, {
            body: {
              channelId: "WebChat",
              channelInfo: await buildChannelInfo(),
              endUsers: [
                {
                  role: MemberRolesEnum.Customer,
                  customerIdentity: { visitorId },
                },
              ],
              initialActivities: [],
              features,
              agentType: AgentTypesEnum.GenerativeAgent,
            },
            headers: { "x-token-refresh": "true" },
          });
        } catch (error) {
          console.error(error);
        }
      },
    });

  const {
    data: conversation,
    error: getConversationError,
    isFetching: getConversationLoading,
  } = useQuery({
    enabled: isChatOpen && !isNewConversation,
    initialData: newConversation,
    queryKey: ["conversation"],
    queryFn: async () => {
      try {
        const conversation =
          await fetcher.get<Conversations.API.Id.Get.Response>(
            `${config.VITE_CONVERSATION_SERVICE_URL}/conversations/${conversationData.id}`,
            {
              headers: {
                Authorization: `Bearer ${conversationData.token}`,
                "x-token-refresh": "true",
              },
            },
          );

        if (conversation.skyeEnabled === false) {
          await getLiveAgentAvailability();
        }

        return conversation;
      } catch (error) {
        console.error(error);
        if (error instanceof FetcherError && error.status === 404) {
          removeLocalConversation();
          removeLocalConversationState();
        }
      }
    },
  });

  const { data: agentAvailability = false, refetch: getLiveAgentAvailability } =
    useQuery({
      enabled:
        isChatOpen &&
        Boolean(conversation?.id) &&
        (isSearching || latestActivityIsSnippet),
      queryKey: ["agentAvailability"],
      queryFn: async () => {
        try {
          return await fetcher.get<Conversations.API.Agents.Get.Response>(
            `${config.VITE_CONVERSATION_SERVICE_URL}/agents/escalation-availability?conversationId=${conversation?.id}`,
          );
        } catch (error) {
          console.error(error);
        }
      },
    });

  const getMostRecentStockNumber = (): string => {
    const viewedVehicles: Array<ViewedVehicle> = JSON.parse(
      viewedVehiclesCookie.ViewedVehicles ?? "[]",
    );

    if (viewedVehicles == null || viewedVehicles.length === 0) {
      // Attempt to parse the current URI for a stock number as a fallback
      const url = window.location.href;
      const match = url.match(/\/car\/(\d{8})(?:[/?&]|$)/);
      if (match && match.length >= 2) {
        const stockNumber = match[1];
        return stockNumber;
      } else {
        return "";
      }
    }

    return (
      viewedVehicles
        .sort((a, b) => b.timestamp - a.timestamp)[0]
        ?.stockNumber?.toString() ?? ""
    );
  };

  const buildChannelInfo = async (): Promise<
    Conversations.Conversation["channelInfo"]
  > => {
    let ipAddress = "";

    try {
      ipAddress = await publicIp.v4();
    } catch (error) {
      console.log(error);
    }

    return {
      myKmxId: myKmxCookie?.userid ?? "",
      accountId: "", // this is crmId, which is no longer in use. May be removed in the future.
      stockNumber: getMostRecentStockNumber(),
      zipCode: visitorCookie?.Zip ?? "",
      visitorId: visitorCookie?.VisitorID ?? "",
      visitNum: visitCounterCookie?.vn ?? "",
      adCode: adCookie?.Adcode ?? "",
      adCodeDateTime: adCookie?.AdCodeDate ?? "",
      ipAddress: ipAddress ?? "",
      originUrl: window.location.href,
      storeId:
        visitorCookie?.StoreId ??
        storeIdCookie.StoreId ??
        nearestStore.store.Id,
      language: navigator?.language ?? "",
    };
  };

  const addMember = (member: Conversations.Members.Member) =>
    queryClient.setQueryData(
      ["conversation"],
      (
        prevConversation: Conversations.Conversation,
      ): Conversations.Conversation => ({
        ...prevConversation,
        members: prevConversation.members.concat([member]),
      }),
    );

  const resetChat = () => {
    removeLocalConversation();
    removeLocalConversationState();
    setCancellable(false);
    setIsRefreshed(false);
    setSearching(false);
    setThinking(false);
    setTyping(false);
    setWaitTime(NaN);
    setWebsocket(undefined);
  };

  const trackEscalationAdobeDataLayerEvent = () => {
    const queryConversation: Conversations.API.Id.Get.Response =
      queryClient.getQueryData(["conversation"])!;
    const userMessagesList = queryConversation.transcript.filter(
      (x) =>
        x.type == ActivityTypesEnum.Message &&
        !x.senderId.includes(AgentTypesEnum.GenerativeAgent),
    );

    trackAdobeDataLayerEvent(ADOBE_DATA_LAYER.EVENT_NAMES.AGENT_ESCALATION, {
      linkName: ADOBE_DATA_LAYER.LINK_NAMES.AGENT_ESCALATION,
      linkPosition: ADOBE_DATA_LAYER.LINK_POSITIONS.CHAT,
      customDetails: {
        menuSelection: {
          chatMenu: `${userMessagesList.at(-2)?.content}, ${
            userMessagesList.at(-1)?.content
          }`,
        },
      },
    });
  };

  const isEscalated = (): boolean =>
    (conversation?.members || []).findIndex(
      (m) => m.associateIdentity.associateId && !m.leftAt,
    ) > -1;

  const receiveActivity = (message: Conversations.Activities.Activity) => {
    const isUserMessage =
      message.senderId === visitorId &&
      message.type === ActivityTypesEnum.Message;

    setSearching(false);
    setCancellable(false);
    setWaitTime(NaN);
    setTyping(false);
    setLatestActivityIsSnippet(false);
    // Only set thinking to true after a user message when not escalated, otherwise set to false
    if (isUserMessage && !isEscalated()) {
      setThinking(true);
    } else if (message.senderId !== visitorId) {
      // Bot or agent response received, stop thinking
      setThinking(false);
    }

    addActivityToTranscript(message);

    if (!conversationState.userInteracted && isUserMessage) {
      setLocalConversationState((prevState) => ({
        ...prevState,
        userInteracted: true,
      }));
    }
  };

  const addActivityToTranscript = (
    message: Conversations.Activities.Activity,
  ) => {
    queryClient.setQueryData(
      ["conversation"],
      (
        prevConversation: Conversations.Conversation,
      ): Conversations.Conversation => ({
        ...prevConversation,
        transcript: prevConversation.transcript.concat([message]),
      }),
    );
  };

  const handleUserLeftEvent = (
    memberId: Conversations.Members.Member["id"],
    timestamp: ISO8601UTCDate,
  ) =>
    queryClient.setQueryData(
      ["conversation"],
      (
        prevConversation: Conversations.Conversation,
      ): Conversations.Conversation => ({
        ...prevConversation,
        members: prevConversation.members.map((member) => {
          if (member.id === memberId) member.leftAt = timestamp;
          return member;
        }),
      }),
    );

  const sendEvent = <T extends Conversations.Activities.Events.Types>(
    eventType: T,
    eventContent: Conversations.Activities.Events.Content<T>,
  ) => {
    if (!conversation || !websocket) return;

    let formattedEventContent = eventContent as string;

    if (typeof eventContent === "object") {
      formattedEventContent = JSON.stringify(eventContent);
    }

    const event: Conversations.Activities.Events.Base = {
      attachments: [],
      category: ActivityTypesEnum.Event,
      content: formattedEventContent,
      conversationId: conversation.id,
      id: "temp-" + Date.now(),
      senderId: visitorId,
      timestamp: new Date().toISOString(),
      type: eventType,
    };

    addActivityToTranscript(event as Conversations.Activities.Activity);
    websocket.send(JSON.stringify(event));
  };

  const sendMessage = (text: string) => {
    if (!conversation || !websocket) return;
    const message: Conversations.Activities.Activity = {
      attachments: [],
      category: ActivityTypesEnum.Message,
      content: text,
      conversationId: conversation.id,
      id: "temp-" + Date.now(),
      senderId: visitorId,
      timestamp: new Date().toISOString(),
      type: ActivityTypesEnum.Message,
    };

    websocket.send(JSON.stringify(message));
    receiveActivity(message);
  };

  const updateStreamData = (conversation: Conversations.Conversation) => {
    const url = new URL(conversation.streamUrl);
    const token = url.searchParams.get("access_token");

    if (!token) return;

    setLocalConversation({
      ...conversationData,
      id: conversation.id,
      token,
    });
  };

  const updateChannelInfo = () => {
    setLocalConversationState((prevState) => ({
      ...prevState,
      pageUrl: window.location.href,
    }));

    (async () => {
      try {
        const channelInfo = await buildChannelInfo();
        sendEvent(EventTypesEnum.UpdateChannelInfo, channelInfo);
      } catch (error) {
        console.error(error);
      }
    })();
  };

  useEffect(() => {
    if (!websocket) return;

    // update channel info when websocket is modified
    updateChannelInfo();

    // update channel info on front-end navigation events
    addEventListener("popstate", updateChannelInfo);
    return () => removeEventListener("popstate", updateChannelInfo);
  }, [websocket]);

  useEffect(() => {
    if (!conversation) return;

    updateStreamData(conversation);
  }, [conversation?.id, conversation?.streamUrl]);

  useEffect(() => {
    if (!conversation?.streamUrl || !isChatOpen) return;

    setConnectionStatus(ConnectionStatusEnum.Pending);
    const ws = new WebSocket(conversation.streamUrl);

    ws.onopen = async function onOpen() {
      setConnectionStatus(ConnectionStatusEnum.Connected);
      setWebsocket(ws);
      setIsRefreshed(true);
    };

    ws.onmessage = (event: MessageEvent) => {
      const activity: Conversations.Activities.Activity = JSON.parse(
        event.data,
      );
      receiveActivity(activity);
      setLatestActivityIsSnippet(activity.type == EventTypesEnum.Snippet);

      switch (activity.category) {
        case ActivityTypesEnum.Event: {
          switch (activity.type) {
            case EventTypesEnum.QueueUpdate: {
              const content: Conversations.Activities.Events.QueueUpdateContent =
                JSON.parse(activity.content);
              setWaitTime(content.estimatedWaitTime);
              break;
            }
            case EventTypesEnum.Searching: {
              const content: Conversations.Activities.Events.SearchingContent =
                activity.content ? JSON.parse(activity.content) : undefined;
              setSearching(true);
              setCancellable(content?.isCancellable ?? false);
              break;
            }
            case EventTypesEnum.Typing: {
              setTyping(true);
              break;
            }
            case EventTypesEnum.UserJoined: {
              const content: Conversations.Activities.Events.UserJoinedContent =
                JSON.parse(activity.content);
              trackEscalationAdobeDataLayerEvent();
              addMember({
                associateIdentity: content.associateIdentity,
                createdAt: activity.timestamp,
                customerIdentity: {
                  ciamId: "",
                  firstName: "",
                  lastName: "",
                  phoneNumber: "",
                  visitorId: "",
                },
                id: content.associateIdentity.associateId,
                joinedAt: activity.timestamp,
                role: content.role,
              });
              break;
            }
            case EventTypesEnum.UserLeft: {
              const content: Conversations.Activities.Events.UserLeftContent =
                JSON.parse(activity.content);
              handleUserLeftEvent(
                content.associateIdentity.associateId,
                activity.timestamp,
              );
              break;
            }
            case EventTypesEnum.Snippet: {
              const content: Conversations.Activities.Messages.Attachments.SnippetContent =
                JSON.parse(activity.attachments[0].contentValue);
              trackEvent("SNIPPET_SERVED", {
                answer: content,
                conversationId: conversation?.id,
                URL: content.TopSearchResultURI,
                fromUtterance: content.FromUtterance,
                visitorId,
                activityId: activity.id,
              });
              break;
            }
          }
          break;
        }
      }
    };

    ws.onclose = () => {
      console.log("Websocket closed");
      setIsRefreshed(false);
    };

    ws.onerror = (event: Event) => {
      console.error("Websocket error", event);
      setConnectionStatus(ConnectionStatusEnum.Error);
      ws.close();
      setWebsocket(undefined);
    };

    return () => {
      ws.close();
    };
  }, [conversation?.streamUrl, isChatOpen, reconnections]);

  useEffect(() => {
    const latestActivity = conversation?.transcript
      .filter((item) => item.type !== EventTypesEnum.UpdateChannelInfo)
      .slice()
      .pop();
    setLatestActivityIsSnippet(latestActivity?.type == EventTypesEnum.Snippet);
  }, [isRefreshed]);

  return (
    <ChatContext.Provider
      value={[
        {
          agentAvailability,
          conversation,
          error: getConversationError,
          isCancellable,
          isEscalated: isEscalated(),
          isLoading: getConversationLoading || createConversationLoading,
          isSearching,
          isThinking,
          isTyping,
          latestActivityIsSnippet,
          reconnections,
          waitTimeSeconds,
          websocket,
          ...value?.[0],
        },
        {
          reconnect: () => setReconnect((prev) => (prev += 1)),
          resetChat,
          sendEvent,
          sendMessage,
          ...value?.[1],
        },
      ]}
    >
      {children}
    </ChatContext.Provider>
  );
};

export const useChat = () => useContext(ChatContext);
