export const MemberRolesEnum = {
  Customer: "Customer",
  LiveAgent: "LiveAgent",
} as const;

declare global {
  namespace Conversations.Members {
    interface IdentityBase {
      firstName: string;
      lastName: string;
    }

    interface AssociateIdentity extends IdentityBase {
      associateId: string;
    }

    interface CustomerIdentity extends IdentityBase {
      ciamId: string;
      phoneNumber: string;
      visitorId: string;
    }

    interface Member {
      associateIdentity: AssociateIdentity;
      createdAt: ISO8601UTCDate;
      customerIdentity: CustomerIdentity;
      id: string;
      joinedAt: ISO8601UTCDate;
      leftAt?: ISO8601UTCDate;
      role: Roles;
    }

    type Roles = ObjectValues<typeof MemberRolesEnum>;
  }
}

export {};
