import { getCookie, setCookie } from "typescript-cookie";

// Stringified<T> is only used because haven't worked out parsing primitive values from cookies yet.
// So although a cookie object may have a primitive value (number, boolean, etc.), it will be represented in string format
// i.e. { 'CookieProperty': 'false' } or { 'CookieProperty': '4566' }
type Stringified<T> = {
  [K in keyof T]: T[K] extends number | boolean | string
    ? `${T[K]}`
    : Stringified<T[K]>;
};

export const CookieKeysEnum = {
  AdCode: "Kmx_Aka_Ad",
  VisitorId: "KmxVisitor_0",
  MyKmxId: "KmxMyKmx_0",
  StoreId: "KmxStore",
  ViewedVehicles: "KMX_ViewedVehicles",
  VisitCounter: "s_vnc365",
} as const;

export interface ViewedVehicle {
  stockNumber: string;
  timestamp: number;
  viewCount: number;
}

interface Cookies {
  [CookieKeysEnum.AdCode]: {
    Adcode: string;
    AdCodeDate: string;
  };
  [CookieKeysEnum.MyKmxId]: {
    userid: string;
  };
  [CookieKeysEnum.StoreId]: {
    StoreId: number;
  };
  [CookieKeysEnum.ViewedVehicles]: {
    ViewedVehicles: string;
  };
  [CookieKeysEnum.VisitCounter]: {
    vn: number;
  };
  [CookieKeysEnum.VisitorId]: {
    IsFirstVisit: boolean;
    Lat: number;
    Lon: number;
    StoreId: number;
    UsingStoreProxy: boolean;
    VisitorID: string;
    Zip: number;
    ZipConfirmed: boolean;
    ZipDate: string; // i.e. 7/18/2024 4:27:58 PM
  };
}

declare global {
  interface Document {
    cookies: Cookies;
  }
}

/**
 * typesafe utility funciton for getting/setting cookies
 */
export const useCookies = <T extends keyof Cookies>(
  cookieName: T,
): [
  cookieValue: Stringified<Cookies[T]>,
  setCookie: (value: Partial<Cookies[T]>) => void,
] => {
  const cookieValue = getCookie(cookieName) ?? "";
  // TODO - some cookies are just strings, not URLSearchParams, so accommodate for that
  const cookieParams = new URLSearchParams(cookieValue);
  const cookieObject = Object.fromEntries(cookieParams) as Stringified<
    Cookies[T]
  >;
  const setCookieValue = (cookieValue: Partial<Cookies[T]>) => {
    setCookie(
      cookieName,
      new URLSearchParams({
        ...cookieObject,
        ...cookieValue,
      } as unknown as Record<string, string>).toString(),
    );
  };
  return [cookieObject, setCookieValue];
};
