import { ActivityTypesEnum } from "..";

export const EventTypesEnum = {
  AgentHandoff: "agentHandoff",
  Cancel: "cancel",
  Link: "link",
  LiveAgentUnavailable: "liveAgentUnavailable",
  MessageFeedback: "messageFeedback",
  QueueUpdate: "queueUpdate",
  Searching: "searching",
  Snippet: "snippet",
  Typing: "typing",
  UpdateChannelInfo: "updateChannelInfo",
  UserJoined: "participantJoined",
  UserLeft: "participantLeft",
} as const;

declare global {
  namespace Conversations.Activities {
    namespace Events {
      interface Base extends Activities.Base {
        category: typeof ActivityTypesEnum.Event;
        content?: unknown;
      }

      type Content<T extends Types> = Extract<Event, { type: T }>["content"];

      type Event =
        | Events.AgentHandoff
        | Events.Cancel
        | Events.Link
        | Events.LiveAgentUnavailable
        | Events.MessageFeedback
        | Events.QueueUpdate
        | Events.Searching
        | Events.Snippet
        | Events.Typing
        | Events.UpdateChannelInfo
        | Events.UserJoined
        | Events.UserLeft;

      type Types = ObjectValues<typeof EventTypesEnum>;
    }
  }
}

export {};
