import React from "react";
import { Box, Stack, Typography } from "@mui/material";
import { LocalStorageKeysEnum, useLocalStorage } from "../../util";
import { useAppInsights, useChat } from "../../context";
import { ConversationRating, RATING_EMOJIS } from "./EmojiUtils";

export const Rating: React.FC = () => {
  const { trackEvent } = useAppInsights();
  const [{ conversation }] = useChat();

  const [conversationData, setLocalConversation] = useLocalStorage(
    LocalStorageKeysEnum.ConversationData,
  );
  const hasRating = conversationData?.rating !== undefined;

  const onSelection = (event: React.MouseEvent<HTMLInputElement>) => {
    const selection = parseInt(event.currentTarget.value) as ConversationRating;

    setLocalConversation({
      ...conversationData,
      rating: selection,
    });

    trackEvent("Chat Rating Selected", {
      conversationId: conversation?.id,
      selection: selection,
    });
  };

  return (
    <Stack>
      <Typography>How was your chat experience?</Typography>
      <Stack direction="row" gap={2} justifyContent="space-around">
        {RATING_EMOJIS.map((emoji, index) => {
          const value = (index - 2) as ConversationRating;

          return (
            <Box
              component="label"
              key={emoji}
              fontSize={32}
              sx={{
                cursor: "pointer",
              }}
            >
              <Box
                component="input"
                disabled={hasRating ? conversationData.rating !== value : false}
                name="rating"
                onClick={onSelection}
                sx={() => ({
                  "&:checked ~ div": {
                    transform: "scale(1.25)",
                  },
                  "&:disabled ~ div": {
                    cursor: "not-allowed",
                    opacity: 0.35,
                  },
                  "&:enabled ~ div:hover": {
                    transform: "scale(1.25)",
                  },
                  display: "none",
                  margin: 0,
                  visibility: "hidden",
                  width: 0,
                })}
                type="radio"
                value={value}
              />
              <Box
                sx={(theme) => ({
                  transition: theme.transitions.duration.shortest + "ms",
                })}
              >
                {emoji}
              </Box>
            </Box>
          );
        })}
      </Stack>
      <Stack justifyContent="space-between" direction="row">
        <Typography variant="caption">Very bad</Typography>
        <Typography variant="caption">Very good</Typography>
      </Stack>
    </Stack>
  );
};

export default Rating;
