import * as useHooks from "usehooks-ts";

export const LocalStorageKeysEnum = {
  ConversationData: "skye-conversation-ids",
  ConversationFeedback: "skye-conversation-feedback",
  ConversationState: "skye-conversation-state",
  NearestStore: "kmx-nearest-store",
} as const;

interface LocalStorage extends WindowLocalStorage {
  [LocalStorageKeysEnum.ConversationData]: {
    dismissed?: boolean;
    id: string;
    rating?: -2 | -1 | 0 | 1 | 2;
    surveyFeedback?: string;
    token: string; // JWT
  };
  [LocalStorageKeysEnum.ConversationState]: {
    pageUrl: string;
    userInteracted: boolean;
  };
  [LocalStorageKeysEnum.NearestStore]: {
    expires: number; // timestamp in milliseconds
    store: Entities.Store.Model;
  };
}

declare global {
  interface Window {
    localStorage: LocalStorage;
  }
}

export const useLocalStorage = <T extends keyof LocalStorage>(
  key: T,
  initialValue: LocalStorage[T] = {} as LocalStorage[T],
) => useHooks.useLocalStorage<LocalStorage[T]>(key, initialValue);
