import { Stack, Typography } from "@mui/material";
import { useChat } from "../../context";

export const skyeOfflineText = "Skye is unavailable for chat";

export const Offline = () => {
  const [chat] = useChat();

  return (
    <Stack
      sx={{
        gap: 3,
        height: "100%",
        padding: 2,
      }}
    >
      <Typography variant="h5">Skye is offline</Typography>
      <Typography>
        {chat.agentAvailability
          ? skyeOfflineText + ", but you can still chat with a live agent."
          : skyeOfflineText + "."}
      </Typography>
    </Stack>
  );
};
