import * as useHooks from "usehooks-ts";

export const SessionStorageKeysEnum = {
  AISearchAnswers: "skyeFeature-aiSearchAnswers",
  AutoEscalate: "skyeFeature-autoEscalate",
  Conversation: "skye-conversation",
  DraftMessage: "skye-conversation-draftMessage",
  Features: "skye-features-2.0",
} as const;

interface SessionStorage extends WindowSessionStorage {
  [SessionStorageKeysEnum.AISearchAnswers]: boolean;
  [SessionStorageKeysEnum.AutoEscalate]: boolean;
  [SessionStorageKeysEnum.Conversation]: Conversations.Conversation;
  [SessionStorageKeysEnum.DraftMessage]: string;
  [SessionStorageKeysEnum.Features]: {
    [key: string]: boolean;
  };
}

declare global {
  interface Window {
    sessionStorage: SessionStorage;
  }
}

export const useSessionStorage = <T extends keyof SessionStorage>(
  key: T,
  initialValue: SessionStorage[T] = {} as SessionStorage[T],
) => useHooks.useSessionStorage<SessionStorage[T]>(key, initialValue);
