// Typesafe wrapper for window.fetch
// Haven't seen anything like this, so made it myself

interface RequestOptions<T> extends Omit<RequestInit, "body"> {
  body?: T;
}

export class FetcherError extends Error {
  public status: number;
  public statusText: string;
  public response: Response;

  constructor(response: Response) {
    super(response.statusText);
    this.status = response.status;
    this.statusText = response.statusText;
    this.response = response;
  }
}

async function fetcherFactory<ResponseBody, RequestBody>(
  url: string,
  options?: RequestOptions<RequestBody>,
): Promise<ResponseBody> {
  const { body, headers = new Headers(), ...rest } = options || {};

  try {
    const response = await fetch(url, {
      body: body ? JSON.stringify(body) : undefined,
      headers: new Headers({
        "Content-Type": "application/json",
        ...headers,
      }),
      ...rest,
    });

    if (!response.ok) {
      throw new FetcherError(response);
    }

    const data = await response.json();
    return data as ResponseBody;
  } catch (error) {
    console.error("Fetch Error:", error);
    throw error;
  }
}

export const fetcher = {
  get<ResponseBody>(
    url: string,
    options?: RequestOptions<null>,
  ): Promise<ResponseBody> {
    return fetcherFactory<ResponseBody, null>(url, {
      ...options,
      method: "GET",
    });
  },
  post<ResponseBody, RequestBody>(
    url: string,
    options: RequestOptions<RequestBody>,
  ): Promise<ResponseBody> {
    return fetcherFactory<ResponseBody, RequestBody>(url, {
      ...options,
      method: "POST",
    });
  },
};
