import React, {
  type PropsWithChildren,
  useContext,
  useEffect,
  useState,
  createContext,
} from "react";
import {
  CookieKeysEnum,
  useCookies,
  ADOBE_DATA_LAYER,
  trackAdobeDataLayer,
  waitForAdobeDataLayer,
} from "../util";
import { config } from "./configuration";
import { ConnectionStatusEnum } from "../components";

type AppContextType = [
  state: {
    config: typeof config;
    connectionStatus: ConnectionStatus;
    isChatOpen: boolean;
    isSurveyModalOpen: boolean;
    myKmxId?: string;
    toggleState: number;
    visitorId: string;
  },
  actions: {
    setConnectionStatus: (status: ConnectionStatus) => void;
    toggleChatWindow: (toggleState?: number) => void;
    toggleSurveyModal: (open?: boolean) => void;
  },
];

export const AppContext = createContext<AppContextType>([
  {},
  {},
] as AppContextType);

interface Props {
  value?: Partial<AppContextType>;
}

export const AppProvider: React.FC<PropsWithChildren<Props>> = ({
  children,
  value,
}) => {
  /**
   * Toggle state:
   * even number: Chat window is closed
   * odd number: Chat window is open
   * making it a number instead of a boolean tells us
   * how many times the chat window has been toggled in this session
   */
  const [toggleState, setToggleState] = useState(0);
  const [isSurveyModalOpen, toggleSurveyModal] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>(
    ConnectionStatusEnum.Pending,
  );
  const [visitorCookie] = useCookies(CookieKeysEnum.VisitorId);
  const [kmxCookie] = useCookies(CookieKeysEnum.MyKmxId);
  const { trackAdobeDataLayerEvent } = trackAdobeDataLayer();

  if (!visitorCookie.VisitorID)
    throw new Error(
      `Skye chat could not be initiated because "${CookieKeysEnum.VisitorId}" cookie with "VisitorID" property was not found.`,
    );

  useEffect(() => {
    if (window.adobeDataLayer) return;

    const adobeScript = document.createElement("script");
    adobeScript.defer = true;
    adobeScript.src = import.meta.env.VITE_ADOBE_DATA_LAYER_SCRIPT!;
    document.head.appendChild(adobeScript);
    return () => {
      document.head.removeChild(adobeScript);
    };
  }, []);

  useEffect(() => {
    const cleanup = waitForAdobeDataLayer(() => {
      trackAdobeDataLayerEvent(ADOBE_DATA_LAYER.EVENT_NAMES.APP_INITIALIZED);
    });

    return cleanup;
  }, [trackAdobeDataLayerEvent]);

  return (
    <AppContext.Provider
      value={[
        {
          config,
          connectionStatus,
          isChatOpen: toggleState % 2 === 1,
          isSurveyModalOpen,
          myKmxId: kmxCookie.userid,
          toggleState,
          visitorId: visitorCookie.VisitorID,
          ...value?.[0],
        },
        {
          setConnectionStatus: (status) => setConnectionStatus(status),
          toggleChatWindow: (nextToggleState) =>
            setToggleState((state) => {
              if (nextToggleState !== undefined) {
                return nextToggleState;
              } else {
                return state + 1;
              }
            }),
          toggleSurveyModal: (open = !isSurveyModalOpen) =>
            toggleSurveyModal(open),
          ...value?.[1],
        },
      ]}
    >
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => useContext(AppContext);
