// Conversation service types:
// https://github.com/CarMax-Internal/convex-conversation-service/blob/main/docs/pubsub-activities/Message.md

// JavaScript objects are recommended over enums
// https://www.typescriptlang.org/docs/handbook/enums.html#objects-vs-enums
export const ConversationStatusesEnum = {
  Active: "active",
} as const;

export const AgentTypesEnum = {
  NotSet: "NotSet",
  LiveAgent: "LiveAgent",
  GenerativeAgent: "GenerativeAgent",
} as const;

export const ChatRoutingTypesEnum = {
  NotSet: "NotSet",
  SalesforceLiveAgentEnglishForcedWait: "SalesforceLiveAgentEnglishForcedWait",
  SalesforceLiveAgentEnglishLow: "SalesforceLiveAgentEnglishLow",
  SalesforceLiveAgentEnglishHigh: "SalesforceLiveAgentEnglishHigh",
  SalesforceLiveAgentSpanish: "SalesforceLiveAgentSpanish",
} as const;

declare global {
  namespace Conversations {
    interface Conversation {
      activeVirtualAgentOrchestrator: string;
      agentType: ObjectValues<typeof AgentTypesEnum>;
      channelId: "WebChat";
      channelInfo: {
        accountId?: string; // this is crmId, which is no longer in use. May be removed in the future.
        adCode: string;
        adCodeDateTime: string;
        ipAddress: string;
        language: string;
        myKmxId: string;
        originUrl: string;
        stockNumber: string;
        storeId: string;
        visitNum: string;
        visitorId: string;
        zipCode: string;
      };
      chatIntents: Array<string>;
      chatRouting: {
        englishQueueId: string;
        forcedWait: boolean;
        previousRoutingType: ObjectValues<typeof ChatRoutingTypesEnum>;
        priorityScore: string;
        routingType: ObjectValues<typeof ChatRoutingTypesEnum>;
        spanishQueueId: string;
      };
      createdAt: ISO8601UTCDate;
      endedAt: ISO8601UTCDate;
      features: Features;
      id: string;
      lastCustomerActivityDateTime: ISO8601UTCDate | null;
      latestWatermark: string;
      liveAgentInfo: {
        affinityToken: string;
        messageFilterRules: Array<MessageFilterRule>;
        sessionId: string;
      };
      members: Array<Conversations.Members.Member>;
      skyeEnabled: boolean;
      status: ObjectValues<typeof ConversationStatusesEnum>;
      streamUrl: string;
      transcript: Array<Conversations.Activities.Activity>;
      updatedAt: ISO8601UTCDate;
      virtualAgentInfo: {
        agentType: ObjectValues<typeof AgentTypesEnum>;
        sessionId: string;
        uri: string | null;
      };
    }

    type Features = Record<string, boolean>;

    interface MessageFilterRule {
      name: string;
      pattern: string;
      replacement: string;
    }

    namespace API {
      namespace Agents {
        namespace Get {
          type Response = boolean;
        }
      }

      namespace Id {
        namespace Get {
          type Response = Conversations.Conversation;
        }
      }
      namespace Post {
        interface Body
          extends Pick<
            Conversations.Conversation,
            "channelId" | "channelInfo" | "features" | "agentType"
          > {
          endUsers: Array<{
            associateIdentity?: Conversations.Members.AssociateIdentity;
            customerIdentity: Partial<Conversations.Members.CustomerIdentity>;
            role: Conversations.Members.Roles;
          }>;
          initialActivities: Array<{
            attachments: Array<Conversations.Activities.Messages.Attachments.Base>;
            content: string;
            senderId: string;
            type: Conversations.Activities.Activity;
          }>;
        }

        type Response = Conversations.Conversation;
      }
    }
  }
}

export {};
