import { Box, Button, Stack, TextField, Typography } from "@mui/material";
import React, { useState } from "react";
import { LocalStorageKeysEnum, useLocalStorage } from "../../util";
import { useAppInsights, useChat } from "../../context";
import { ConversationRating, getEmojiFromRating } from "./EmojiUtils";

const MAX_FEEDBACK_LENGTH = 500;

interface Props {
  selectedRating?: ConversationRating;
  onFocus?: () => void;
  onBlur?: () => void;
}

export const Microsurvey: React.FC<Props> = ({
  selectedRating,
  onFocus,
  onBlur,
}) => {
  const { trackEvent } = useAppInsights();
  const [surveyMessage, setSurveyMessage] = useState("");
  const [{ conversation }] = useChat();
  const [conversationData, setLocalConversation] = useLocalStorage(
    LocalStorageKeysEnum.ConversationData,
  );
  const formRef = React.useRef<HTMLFormElement>(null);

  const hasFeedback = conversationData?.surveyFeedback !== undefined;
  const isSubmitDisabled = surveyMessage.trim().length === 0 || hasFeedback;
  const selectedEmoji = getEmojiFromRating(selectedRating);

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    if (hasFeedback) return;

    if (!formRef.current?.checkValidity()) {
      formRef.current?.reportValidity();
      return;
    }

    const trimmedMessage = surveyMessage.trim();

    setLocalConversation({
      ...conversationData,
      surveyFeedback: trimmedMessage,
    });

    trackEvent("Post-Emoji Microsurvey Filled", {
      conversationId: conversation?.id,
      surveyFeedback: trimmedMessage,
    });
  };

  return (
    <Stack
      component="form"
      ref={formRef}
      onSubmit={handleSubmit}
      sx={{
        gap: 2,
        position: "relative",
        width: "17rem",
      }}
    >
      <Stack direction="row" gap={1} alignItems="flex-end">
        <Typography sx={{ fontWeight: "bold" }}>You selected</Typography>
        <Box fontSize={32}>{selectedEmoji}</Box>
      </Stack>
      <TextField
        id="post-emoji-microsurvey"
        name="emoji-microsurvey"
        label="Can you tell us more?"
        value={surveyMessage}
        onChange={(e) => setSurveyMessage(e.target.value)}
        onFocus={onFocus}
        onBlur={onBlur}
        disabled={hasFeedback}
        multiline
        slotProps={{
          htmlInput: {
            maxLength: MAX_FEEDBACK_LENGTH,
            minLength: 1,
            maxRows: 4,
          },
          inputLabel: {
            required: false,
          },
        }}
        required // required for HTML validation
      />
      <Button
        disabled={isSubmitDisabled}
        variant={hasFeedback ? "text" : "contained"}
        type="submit"
      >
        {hasFeedback ? "Thank you! ✓" : "Submit"}
      </Button>
    </Stack>
  );
};
